update public.ws_modules set title = $ws$המדריך מלמד את רובי מול הכיתה$ws$, summary = $ws$סדר יום: העין של המדריך (5 ד׳) · מלמדים את רובי (8 ד׳) · בודקים: מנחשים לפני (8 ד׳) · רמזור הרובוט (6 ד׳)$ws$, module_type = $ws$demo$ws$, pipeline_stage = $ws$demo$ws$, duration_minutes = 27, objectives = array[$ws$לראות מכונה לומדת חפצים של הכיתה בזמן אמת, בכפתור אחד של המדריך.$ws$, $ws$לנבא לפני התוצאה אם הרובוט יזהה או לא, ולהשוות.$ws$, $ws$להבין שזיהוי הוא רק צעד ראשון ואחריו באה פעולה (רמזור הרובוט).$ws$]::text[], exercises = $ws$[{"title": "מלמדים את רובי", "instructions": "1. הכיתה מחליטה על שני חפצים שהרובוט ילמד, לדוגמה כוס ומחק.\n2. ילד מביא את החפץ אל השולחן של המדריך. המדריך מניח את החפץ על בד אפור על מעמד, בלי יד בפריים, ומשנה את תנוחתו שלוש פעמים; המכשיר מצלם 10 תמונות.\n3. לאחר שני החפצים סופרים בקול עד 30 שניות ולוחצים ״למד״ בנוכחות הכיתה.\n4. מוודאים שאין אף פנים בתמונה. אם הופיעה יד של ילד, מוחקים את התמונה מול הכיתה.", "kind": "class", "tool_hook": "pocket_trainer"}, {"title": "ניחוש לפני תוצאה", "instructions": "1. ילד מביא חפץ שהרובוט לא ראה (כוס אחרת).\n2. כל ילד מרים כרטיס: עיגול ירוק ״כן״ (יזהה) או ריבוע אדום ״לא״ (לא יזהה). המדריך סופר בקול: ״14 ירוק, 9 אדום״. המצלמה נשארת על השולחן ולא סופרת כרטיסים.\n3. מראים את החפץ על השולחן במצלמה החיה. רובי אומר מהמקרן: ״ראיתי 10 תמונות של כוס ו-10 של מחק. זה דומה למה שראיתי, אז אני אומר: כוס.״ או ״זה לא דומה לשום דבר שראיתי.״ פס ירוק מלא: בטוח. פס צהוב: לא בטוח. פס אדום או ריק: לא מכיר.\n4. אם רובי טעה, המדריך אומר את הסיבה בתוך 30 שניות (״לא הראינו לו כוס כחולה״), שואל ״מה לא הראינו לו?״ ורושם ציור קטן על הלוח. מוסיפים דוגמה אחת ובודקים שוב.", "kind": "class", "tool_hook": "live_cam"}, {"title": "רמזור הרובוט", "instructions": "1. קובעים חוק קצר: אם רובי רואה כוס, הכיתה מרימה עיגול ירוק ״כן״, אחרת ריבוע אדום ״לא״.\n2. המדריך מראה לרובי כוס מלאה, כוס חצי מוסתרת ופקק של בקבוק.\n3. הכיתה מרימה כרטיס לפי מה שרובי אומר, ולא לפי מה שהם יודעים. מנסים להבין למה לפעמים לא מסכימים.", "kind": "class", "tool_hook": "live_cam"}]$ws$::jsonb, materials = $ws$[{"label": "מכשיר המדריך עם אפליקציית ״מאמן הכיס״ במצב מדריך", "kind": "supply"}, {"label": "חצובה או מעמד, בד אפור או דף אפור על השולחן", "kind": "supply"}, {"label": "כרטיס לכל ילד: עיגול ירוק עם המילה ״כן״ מצד אחד, ריבוע אדום עם המילה ״לא״ מהצד השני", "kind": "supply"}, {"label": "10 חפצים של הכיתה ועוד 4 חפצים מבלבלים של המדריך", "kind": "supply"}, {"label": "מקרן", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקורות: [05 #9], [02 §5 א-ב], [03 §6 א-ג], [08 P11]. הנחיות משרד החינוך (ינואר 2025): בכיתות א-ג אין כלי בינה מלאכותית בידי תלמידים. לכן רק המדריך מחזיק את המכשיר, הילדים רק מביאים חפצים ומצביעים. המצלמה מופנית לשולחן, לתמונה מודפסת או לחפץ בלבד, ולעולם לא לכיתה ולא לילדים; ההצבעה נספרת בקול על ידי המדריך (״14 ירוק, 9 אדום״), לא על ידי המצלמה. לרובוט יש שם אחד: רובי. רובי מדבר רק במשפט קבוע: ״ראיתי 10 תמונות של כוס ו-10 של מחק. זה דומה למה שראיתי, אז אני אומר: כוס.״ ובטעות: ״זה לא דומה לשום דבר שראיתי.״ המדריך: ״הוא לא יודע, הוא התאים למה שראה.״ אף פעם לא ״הוא הבין״, ״אני יודע״ או ״אני חכם״. אין מספרים ואין אחוזים. כל טעות מסתיימת ב״מוסיפים דוגמה אחת ובודקים שוב״.

── סדר יום ──
• 5 ד׳ · העין של המדריך - המדריך מראה את המכשיר שלו: ״זו העין של רובי. רק אני לוחץ על הכפתור. היא מסתכלת על השולחן ולא עליכם״. מכוונים אל שולחן עם בד אפור.
• 8 ד׳ · מלמדים את רובי - הכיתה בוחרת שני חפצים (כוס ונעל). ילדים מביאים חפצים בתורם, המדריך מניח כל חפץ על בד אפור על מעמד (בלי יד בפריים) ומצלם 10 תמונות לכל מחלקה, סופרים יחד עד 30 והרובוט למד.
• 8 ד׳ · בודקים: מנחשים לפני - ילד מביא חפץ חדש שרובי לא ראה. כל ילד מרים כרטיס (עיגול ירוק ״כן״ או ריבוע אדום ״לא״), המדריך סופר בקול ״14 ירוק, 9 אדום״. רק אז מראים את החפץ על השולחן, רובי אומר את המשפט שלו ורואים את הפס (ירוק בטוח, צהוב לא בטוח). טעות: הסיבה תוך 30 שניות, מוסיפים דוגמה אחת ובודקים שוב.
• 6 ד׳ · רמזור הרובוט - קובעים חוק: אם רובי רואה כוס, הכיתה מרימה עיגול ירוק ״כן״, אחרת ריבוע אדום ״לא״. מנסים חפץ חצי מוסתר ושואלים מה קורה.

── הערכה ──
ראיות: הכיתה ניבאה לפחות 3 פעמים לפני התוצאה, ורשמה על הלוח לפחות שני דברים שהרובוט לא ידע.
הושלם כאשר: הרובוט טעה לפחות פעם אחת והילדים הציעו מה להוסיף, ושלושה ילדים לפחות ניבאו לפני תוצאה.

── התאמות ──
קל יותר: מחלקה אחת בלבד (כוס מול לא כוס) והמדריך מפעיל את הרמזור בלי לשאול מה קורה כשהחפץ חצי מוסתר.
מאתגר יותר: הכיתה בוחרת חפץ ״מתחזה״ שיבלבל את הרובוט, ומסבירה אחרי הכישלון איך ללמד אותו להבדיל.$ws$, tags = array[$ws$band:a-b$ws$, $ws$audience:school$ws$, $ws$level:L0$ws$, $ws$ai-mode:facilitator-only$ws$, $ws$live_demo$ws$, $ws$traffic_light$ws$]::text[], requires_app = true, version = version + 1, updated_at = now()
 where slug = $ws$ab-facilitator-live-demo$ws$
