update public.ws_modules set title = $ws$בדיקת מושגים בתמונות: לפני ואחרי (א-ב)$ws$, summary = $ws$סדר יום: הסבר (1 ד׳) · שבע תמונות (6 ד׳) · אסיפה (1 ד׳)$ws$, module_type = $ws$practice$ws$, pipeline_stage = null, duration_minutes = 8, objectives = array[$ws$למדוד התקדמות בהבנת חמישה רעיונות: ״מלמדים בדוגמאות״, ״צריך הרבה סוגים״, ״בודקים על דבר חדש״, ״המחשב רואה ריבועים״, ״לא מצלמים אנשים״.$ws$, $ws$לתת למדריך תמונה כיתתית (לא אישית) של מה שהילדים כבר יודעים.$ws$, $ws$לעשות זאת בלי קריאה וכתיבה מצד הילדים.$ws$]::text[], exercises = $ws$[{"title": "שבע תמונות", "instructions": "1. מחלקים דף אחד לילד עם שבע שורות ובכל שורה שניים עד ארבעה ציורים, האחרון תמיד סימן שאלה: ״לא יודע/ת״.\n2. המדריך קורא שאלה, סופר עד חמש בקול, והילדים מקיפים תמונה אחת.\n3. בפעם הראשונה לא חושפים תשובות. בפעם השנייה (post) חושפים את שתי השאלות שהכי הרבה ילדים טעו בהן.\n4. המדריך מסכם לכל שאלה כמה ילדים בחרו בכל תמונה (ספירת ידיים או ספירת דפים) ומתעד בטבלה כיתתית.", "kind": "individual", "tool_hook": "none", "concept_check_id": "cc-ab", "questions": [{"q": "איזה ילד מלמד את המחשב להכיר כוסות?", "options": ["ילד מראה למצלמה הרבה כוסות שונות", "ילד אומר פעם אחת ״זו כוס״ ומסתובב", "לא יודע/ת"], "answer": 0, "image_brief": ["ילד ליד שולחן עם חמש כוסות שונות ומצלמה על חצובה", "ילד מצביע על כוס אחת וידו השנייה נשענת על הקיר", "סימן שאלה"], "id": "ab_teach"}, {"q": "המחשב ראה רק כוסות אדומות. עכשיו מראים לו כוס כחולה. מה יקרה?", "options": ["פרצוף שמח מאוד: הוא בטוח", "פרצוף מהסס: הוא לא בטוח", "פרצוף עצוב: הוא לא מכיר שום דבר", "לא יודע/ת"], "answer": 1, "core": "variety", "image_brief": ["סמיילי מחייך ברחבות", "סמיילי עם גבה מורמת", "סמיילי עם דמעה", "סימן שאלה"], "id": "ab_variety"}, {"q": "מה המחשב רואה כשהוא מסתכל בתמונה?", "options": ["תמונה כמו שאנחנו רואים", "ריבועים קטנים עם מספרים", "מילים שמתארות את התמונה", "לא יודע/ת"], "answer": 1, "image_brief": ["תמונה צבעונית של כוס", "רשת של ריבועים קטנים שחורים ולבנים", "בועת דיבור עם מילים", "סימן שאלה"], "id": "ab_pixels"}, {"q": "איך יודעים אם המחשב באמת למד?", "options": ["מראים לו את אותה כוס שהוא התאמן עליה", "מראים לו כוס חדשה שהוא לא ראה", "לא יודע/ת"], "answer": 1, "core": "train_test", "image_brief": ["אותה כוס אדומה פעמיים", "כוס אדומה ולידה כוס ירוקה חדשה", "סימן שאלה"], "id": "ab_test"}, {"q": "הרובוט ראה רק נעלי ספורט. עכשיו מראים לו סנדל והוא אומר ״לא נעל״. למה?", "options": ["כי הרובוט טיפש", "כי לא הראינו לו סנדלים", "כי סנדל זה לא נעל", "לא יודע/ת"], "answer": 1, "core": "bias", "image_brief": ["רובוט עם פרצוף קצר רוח", "ערימת נעלי ספורט ללא סנדל", "סנדל עם סימן X", "סימן שאלה"], "id": "ab_bias"}, {"q": "מה מצלמים בסדנה?", "options": ["כוס", "פנים של חבר", "פנים של המורה", "לא יודע/ת"], "answer": 0, "image_brief": ["כוס על שולחן", "ציור של פנים עם סימן אסור", "ציור של פנים עם סימן אסור", "סימן שאלה"], "id": "ab_privacy"}, {"q": "בתמונה ארבע כוסות. הרובוט סימן שלוש מהן. כמה כוסות הוא פספס?", "options": ["אחת", "שתיים", "אפס", "לא יודע/ת"], "answer": 0, "image_brief": ["ארבע כוסות, שלוש מסומנות בעיגול ואחת בלי סימון", "ארבע כוסות, שתיים מסומנות בעיגול ושתיים בלי סימון", "ארבע כוסות, כולן מסומנות בעיגול", "סימן שאלה"], "id": "ab_count"}]}, {"title": "טבלת סיכום כיתתית", "instructions": "1. המדריך מכין טבלה עם שבע שורות (שאלות) ועמודה לכל תמונה.\n2. אחרי איסוף הדפים סופרים לכל שאלה כמה ילדים בחרו בכל תמונה.\n3. שומרים את הטבלה לפי תאריך (pre או post) ללא שמות.\n4. ב-post מניחים את שתי הטבלאות זו ליד זו ומסמנים באיזו שאלה ירד מספר הטועים.", "kind": "class", "tool_hook": "none"}]$ws$::jsonb, materials = $ws$[{"label": "דף שאלון בתמונות לכל ילד (מודפס, 7 שורות)", "kind": "supply"}, {"label": "עיפרון", "kind": "supply"}, {"label": "קופסה לאיסוף דפים אנונימיים", "kind": "supply"}, {"label": "מקרן או הדפסה גדולה של התמונות", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$אותם פריטים ב-pre וב-post. בכל שאלה האפשרות האחרונה היא ״לא יודע/ת״ (באיור: סימן שאלה); מדווחים ספירות לפריט, אחוזים רק מ-15 משיבים. מקור: [06 §4.1]. אנונימיות היא תנאי. מדווחים ״כמה ילדים מתוך הכיתה״ ולא אחוזים ולא ציונים אישיים. אותו שאלון בדיוק בפעם הראשונה ובאחרונה. שלוש השאלות שמסומנות core שקולות מבחינת המושג (train_test, variety, bias) בכל הרצועות אך מנוסחות לגיל; מודדים שיפור בתוך רצועה ולא משווים בין רצועות.

── סדר יום ──
• 1 ד׳ · הסבר - אומרים: ״זה משחק תמונות, אין טעות, אני רק רוצה לדעת מה אתם חושבים״.
• 6 ד׳ · שבע תמונות - המדריך מקריא כל שאלה, מקרין את שתי או שלוש התמונות, והילדים מקיפים בעיפרון את התשובה על דף עם אייקונים.
• 1 ד׳ · אסיפה - אוספים את הדפים בקופסה אחת, בלי שמות.

── הערכה ──
ראיות: ספירה כיתתית לכל תמונה בכל שאלה, בשני המועדים (pre ו-post).
הושלם כאשר: כל דפי הכיתה נאספו ונספרו בשני המועדים.

── התאמות ──
