update public.ws_modules set title = $ws$המחשב שנכשל: מי אמר שהמחשב כבר יודע?$ws$, summary = $ws$סדר יום: ניחוש (3 ד׳) · מאמנים 5 דוגמאות (5 ד׳) · בודקים (5 ד׳) · שלוש סיבות (5 ד׳)$ws$, module_type = $ws$mixed$ws$, pipeline_stage = $ws$intro$ws$, duration_minutes = 18, objectives = array[$ws$לשבור את ההנחה ״המחשב כבר יודע הכול״ ב-10 הדקות הראשונות.$ws$, $ws$לנבא מה מחשב שלמד מעט דוגמאות יזהה ומה לא, ולבדוק.$ws$, $ws$לנסח שלוש סיבות לכך שהמחשב טעה.$ws$]::text[], exercises = $ws$[{"title": "הניחוש", "instructions": "1. המדריך מחזיק כוס ושואל: ״המחשב כבר יודע מה זו כוס?״\n2. כל ילד מרים כרטיס: עיגול ירוק ״כן״ או ריבוע אדום ״לא״. המדריך סופר בקול (״14 ירוק, 9 אדום״) ורושם על הלוח.\n3. לאחר הפעילות חוזרים לספירה ושואלים: ״מה דעתכם עכשיו?״", "kind": "class", "tool_hook": "none"}, {"title": "שלוש סיבות", "instructions": "1. המדריך מראה את הטעות החזקה ביותר (בקבוק על רצפה שזוהה ככוס בביטחון גבוה).\n2. בכיתות ג-ד המדריך אומר קודם את הסיבה בתוך 30 שניות (״הוא ראה רק שולחן לבן״) והקבוצות מוסיפות עוד שתיים; בכיתות ה-ו הקבוצות כותבות שלוש סיבות לבד לפני ההסבר (שתי דקות כתיבה).\n3. מקריאים סיבה אחת מכל קבוצה ומסמנים כוכב ליד הסיבה שחוזרת (שתי דקות).\n4. מסיימים במשפט אחד: ״המחשב יודע רק מה שהראינו לו״.", "kind": "group", "tool_hook": "live_cam"}]$ws$::jsonb, materials = $ws$[{"label": "מכשיר המדריך עם מאמן הכיס במצב מדריך", "kind": "supply"}, {"label": "כוס לבנה, כוס כחולה, בקבוק ירוק, וחפץ שלישי שנכשל בוודאות (נבדק יום קודם)", "kind": "supply"}, {"label": "מודל גיבוי שנכשל בוודאות על המכשיר, ומחלקה שלישית ״שולחן ריק״ מוכנה", "kind": "supply"}, {"label": "בד לבן לשולחן", "kind": "supply"}, {"label": "פתקים ועפרונות", "kind": "supply"}, {"label": "כרטיס לכל ילד: עיגול ירוק ״כן״ / ריבוע אדום ״לא״", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקורות: [02 §6 המלצה 5], [01 §5], [08 §4]. הכשל מתוכנן: אל תמנעו אותו. צרו אותו בכוונה בכיתה. בדקו את הכשל יום קודם: אם הבקבוק מזוהה נכון על הרצפה, הוסיפו מחלקה שלישית ״שולחן ריק״ או בדקו כוס שקופה; מודל גיבוי שנכשל בוודאות מוכן במכשיר. הפתיחה צריכה להסתיים בתוך 10 הדקות הראשונות של הלמידה (pre ממלאים בכניסה). בכיתות ג-ד המכשיר רק של המדריך, ורק לאחר אישור כתוב (ai_gate). בכיתות ה-ו בעיקר אותו מבנה, כשהקבוצות מנסות להפיל בעצמן בשלב מאוחר יותר. המצלמה של המדריך מופנית לשולחן ולחפצים בלבד, לעולם לא לכיתה; אין פנים או ידיים של ילדים בפריים. ג-ד: ההסבר לכשל בתוך 30 שניות מהחשיפה; ה-ו: הקבוצות משערות קודם. מול כיתות ג-ד אומרים ״המחשב״ ולא ״מודל״.

── סדר יום ──
• 3 ד׳ · ניחוש - המדריך מחזיק כוס ושואל: ״המחשב כבר יודע מה זה כוס?״ הכיתה מצביעה בכרטיסים (עיגול ירוק ״כן״, ריבוע אדום ״לא״), המדריך סופר בקול ומתעד.
• 5 ד׳ · מאמנים 5 דוגמאות - המדריך מלמד את המחשב מול הכיתה (המצלמה על השולחן): 5 תמונות כוס לבנה על שולחן לבן, 5 תמונות בקבוק ירוק על שולחן לבן.
• 5 ד׳ · בודקים - מראים: אותה כוס (מצליח), כוס כחולה (לא בטוח), הבקבוק על רצפת הכיתה (טועה בביטחון גבוה).
• 5 ד׳ · שלוש סיבות - בקבוצות של שלושה כותבים שלוש סיבות לטעות (2 דקות), מקריאים ומסמנים כוכב על סיבה שחוזרת (2 דקות), ומסכמים במשפט (דקה). אוספים על הלוח.

── הערכה ──
ראיות: ספירת הניחוש לפני ואחרי, ושלוש סיבות על הלוח.
הושלם כאשר: הכיתה ניבאה לפני כל בדיקה, וכתבה שלוש סיבות לטעות לפחות.

── התאמות ──
קל יותר: אימון על שני חפצים שונים מאוד, והמדריך מציע את שתי הסיבות הראשונות ומבקש מהכיתה להוסיף אחת.
מאתגר יותר: הקבוצות מציעות איזה תנאי היו משנות כדי שהמודל לא ייפול (למשל להוסיף רקע, להוסיף תאורה).$ws$, tags = array[$ws$band:c-d$ws$, $ws$band:e-f$ws$, $ws$audience:school$ws$, $ws$level:L1$ws$, $ws$level:L2$ws$, $ws$ai-mode:facilitator-device$ws$, $ws$failure_by_design$ws$, $ws$folk_theory$ws$]::text[], requires_app = true, version = version + 1, updated_at = now()
 where slug = $ws$x-failed-model-opener$ws$
