update public.ws_modules set title = $ws$אני רואה ריבועים: כמה צריך כדי לזהות?$ws$, summary = $ws$סדר יום: 8 על 8 (3 ד׳) · 16 ו-32 (6 ד׳) · 128 על 128 (6 ד׳)$ws$, module_type = $ws$theory$ws$, pipeline_stage = $ws$intro$ws$, duration_minutes = 15, objectives = array[$ws$להסביר שתמונה בנויה מריבועים קטנים ושמחשב מקבל רק מספרים.$ws$, $ws$לגלות שיותר ריבועים נותנים יותר פרטים.$ws$, $ws$לחבר את הרעיון למה שהמחשב ״רואה״.$ws$]::text[], exercises = $ws$[{"title": "מנחשים ומעדכנים", "instructions": "1. המדריך מציג תמונה בארבע רזולוציות: 8, 16, 32 ו-128 ריבועים לצלע.\n2. בכל שלב כל ילד כותב מילה אחת על לוחון: מה אני חושב שזה?\n3. בסוף מרימים את הלוחונות ומשווים: מתי הכיתה ידעה?\n4. שואלים: ״מה משתנה בין התמונות? מה קורה למספרים?״", "kind": "individual", "tool_hook": "none"}, {"title": "כמה ריבועים?", "instructions": "1. כל קבוצה מקבלת דף רשת 10 על 10 ושואלת: כמה ריבועים יש?\n2. מציירים על דף: מה היה קורה אם היו 1000 ריבועים?\n3. המדריך מסכם: מחשב מקבל רשימת מספרים אחת לכל ריבוע, ומשם הוא לומד.", "kind": "group", "tool_hook": "none"}]$ws$::jsonb, materials = $ws$[{"label": "אותה תמונה (חתול או כוס) מודפסת ב-4 רזולוציות על A3", "kind": "supply"}, {"label": "לוחוני מחיק ומרקרים לכל ילד", "kind": "supply"}, {"label": "דפי רשת 10 על 10", "kind": "supply"}, {"label": "תמונה בלי אנשים", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקור: [05 #17], [02 §2.2]. אותו עיקרון כמו ״ציור במספרים״ של מפגש 1 בסדנה הרגילה, כאן בגרסה קצרה בלי מספרים. לא נכנסים לעומק של 3 ערוצי צבע. אם יש פחות מ-10 דקות מדלגים על חלק 128. הזום על הריבועים נעשה על תמונה מודפסת או על חפץ שמונח על שולחן המדריך, לעולם לא על הכיתה ולא על ילדים; אם משתמשים במצלמת המדריך, היא מופנית לשולחן בלבד.

── סדר יום ──
• 3 ד׳ · 8 על 8 - מציגים תמונה של חתול בגודל 8 על 8. כל ילד כותב על לוחון מה לדעתו בתמונה.
• 6 ד׳ · 16 ו-32 - מציגים 16 על 16 ואחר כך 32 על 32. בכל שלב מעדכנים ניחוש. מי שינה? למה?
• 6 ד׳ · 128 על 128 - מציגים את התמונה המלאה. הכיתה מחשבת: כמה ריבועים יש בתמונה אחת?

── הערכה ──
ראיות: הלוחונות בשלושת השלבים והמשפט ״יותר ריבועים, יותר פרטים״.
הושלם כאשר: הכיתה שינתה ניחוש לפחות פעם אחת ואמרה במשפט שמחשב רואה ריבועים של מספרים.

── התאמות ──
קל יותר: שלוש רזולוציות בלבד (8, 32, 128).
מאתגר יותר: הילדים מנחשים כמה ריבועים צריך כדי לזהות בקבוק בקצה החדר.$ws$, tags = array[$ws$band:c-d$ws$, $ws$audience:school$ws$, $ws$level:L1$ws$, $ws$ai-mode:none$ws$, $ws$pixels$ws$]::text[], requires_app = false, version = version + 1, updated_at = now()
