update public.ws_modules set title = $ws$מפילים את המחשב: כדור על דשא ומשחק ההפלה$ws$, summary = $ws$סדר יום: כדור על דשא (7 ד׳) · משחק ההפלה (13 ד׳)$ws$, module_type = $ws$practice$ws$, pipeline_stage = $ws$evaluate$ws$, duration_minutes = 20, objectives = array[$ws$להבין שהמחשב לומד גם את הרקע ולא רק את החפץ.$ws$, $ws$להפיל את המחשב במשחק שיתופי ולתעד כל נפילה.$ws$, $ws$לנסח סיבה לכל נפילה במשפט אחד.$ws$]::text[], exercises = $ws$[{"title": "כדור על דשא", "instructions": "1. זוג מקבל 6 כרטיסים: ״כדור על דשא״ (3), ״כדור על שולחן״ (1), ״דשא בלי כדור״ (2).\n2. אחד ״מאמן״ את החבר רק עם כרטיסי כדור על דשא ואומר ״כדור״.\n3. מראים לחבר דשא ריק. הוא עונה. שואלים: מה הוא למד: כדור או דשא?\n4. מציעים איזה כרטיס להוסיף כדי לתקן.", "kind": "group", "tool_hook": "none"}, {"title": "ספר הטעויות", "instructions": "1. הכיתה בוחרת שלושה חפצים שהמחשב מכיר (מחק, מספריים, מדבקה).\n2. זוג מביא ניסיון להפלה: חפץ דומה, רקע חדש, חצי מוסתר או במקום חשוך.\n3. הזוג מניח את החפץ על שולחן ההפלה והמדריך מפעיל את המצלמה החיה על השולחן בלבד. אם המחשב טעה, כל הכיתה צועקת ״הפלנו!״, המדריך אומר את הסיבה תוך 30 שניות (״הוא למד את הרקע״) ומוסיפים שורה לספר.\n4. בכל שורה ארבע עמודות: מה הראינו, מה הוא אמר, למה לדעתנו, התיקון עבד? (העמודה הרביעית מתמלאת ב״מתקנים נפילה אחת״).", "kind": "group", "tool_hook": "live_cam"}]$ws$::jsonb, materials = $ws$[{"label": "כרטיסי תמונה (6 לכל זוג)", "kind": "supply"}, {"label": "מכשיר המדריך עם המודל מהמפגש הקודם", "kind": "supply"}, {"label": "ספר טעויות על נייר A1 בארבע עמודות: מה הראינו / מה הוא אמר / למה לדעתנו / התיקון עבד?", "kind": "supply"}, {"label": "חפצים מבלבלים ורקעים (בד אדום, דף משובץ)", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקורות: [05 #14], [02 §5 ג-ד]. התחרות היא של הכיתה נגד המודל, לא של זוג נגד זוג. כל נפילה היא ״ניצחון״ של הכיתה, והמדריך מדגים אותו בחיוך. בכיתות ג-ד אין מילים ״הטיה״ ו״מעקב״, אומרים ״הוא למד את הרקע״. המדריך אומר את הסיבה לכל נפילה בתוך 30 שניות מהחשיפה, ורק אז הכיתה כותבת. אחרי המשחק בוחרים נפילה אחת לתיקון במודול cd-fix-one-fall. מול הילדים אומרים ״המחשב״ ולא ״מודל״.

── סדר יום ──
• 7 ד׳ · כדור על דשא - בפעילות בלי מכשיר מאמנים חבר רק עם כרטיסי ״כדור על דשא״ ומראים לו דשא ריק. הוא אומר ״כדור״. למה?
• 13 ד׳ · משחק ההפלה - זוגות מביאים תרגיל להפלת המחשב של הכיתה (חפץ דומה, רקע חדש, חצי מוסתר) על שולחן ההפלה; המצלמה על השולחן בלבד. הכיתה סופרת כמה פעמים הפילה, המדריך אומר את הסיבה תוך 30 שניות, ורושמים ב״ספר הטעויות״.

── הערכה ──
ראיות: ספר הטעויות עם 6 שורות לפחות, ותשובה של כל זוג בכרטיסי כדור על דשא.
הושלם כאשר: הכיתה הפילה את המודל לפחות 5 פעמים וכתבה סיבה מנומקת ל-3 מהן.

── התאמות ──
קל יותר: המדריך מציע את הנפילות הראשונות והכיתה מנחשת למה.
מאתגר יותר: כל זוג מתכנן נפילה לפני שמנסה, ואחר כך משווה בין התחזית לתוצאה.$ws$, tags = array[$ws$band:c-d$ws$, $ws$audience:school$ws$, $ws$level:L1$ws$, $ws$ai-mode:facilitator-device$ws$, $ws$background_trap$ws$, $ws$failure_by_design$ws$]::text[], requires_app = true, version = version + 1, updated_at = now()
 where slug = $ws$cd-break-the-model-game$ws$
   and (title, summary, module_type, pipeline_stage, duration_minutes, objectives, exercises, materials, facilitator_notes, tags, requires_app) is distinct from ($ws$מפילים את המחשב: כדור על דשא ומשחק ההפלה$ws$, $ws$סדר יום: כדור על דשא (7 ד׳) · משחק ההפלה (13 ד׳)$ws$, $ws$practice$ws$, $ws$evaluate$ws$, 20, array[$ws$להבין שהמחשב לומד גם את הרקע ולא רק את החפץ.$ws$, $ws$להפיל את המחשב במשחק שיתופי ולתעד כל נפילה.$ws$, $ws$לנסח סיבה לכל נפילה במשפט אחד.$ws$]::text[], $ws$[{"title": "כדור על דשא", "instructions": "1. זוג מקבל 6 כרטיסים: ״כדור על דשא״ (3), ״כדור על שולחן״ (1), ״דשא בלי כדור״ (2).\n2. אחד ״מאמן״ את החבר רק עם כרטיסי כדור על דשא ואומר ״כדור״.\n3. מראים לחבר דשא ריק. הוא עונה. שואלים: מה הוא למד: כדור או דשא?\n4. מציעים איזה כרטיס להוסיף כדי לתקן.", "kind": "group", "tool_hook": "none"}, {"title": "ספר הטעויות", "instructions": "1. הכיתה בוחרת שלושה חפצים שהמחשב מכיר (מחק, מספריים, מדבקה).\n2. זוג מביא ניסיון להפלה: חפץ דומה, רקע חדש, חצי מוסתר או במקום חשוך.\n3. הזוג מניח את החפץ על שולחן ההפלה והמדריך מפעיל את המצלמה החיה על השולחן בלבד. אם המחשב טעה, כל הכיתה צועקת ״הפלנו!״, המדריך אומר את הסיבה תוך 30 שניות (״הוא למד את הרקע״) ומוסיפים שורה לספר.\n4. בכל שורה ארבע עמודות: מה הראינו, מה הוא אמר, למה לדעתנו, התיקון עבד? (העמודה הרביעית מתמלאת ב״מתקנים נפילה אחת״).", "kind": "group", "tool_hook": "live_cam"}]$ws$::jsonb, $ws$[{"label": "כרטיסי תמונה (6 לכל זוג)", "kind": "supply"}, {"label": "מכשיר המדריך עם המודל מהמפגש הקודם", "kind": "supply"}, {"label": "ספר טעויות על נייר A1 בארבע עמודות: מה הראינו / מה הוא אמר / למה לדעתנו / התיקון עבד?", "kind": "supply"}, {"label": "חפצים מבלבלים ורקעים (בד אדום, דף משובץ)", "kind": "supply"}]$ws$::jsonb, $ws$מקורות: [05 #14], [02 §5 ג-ד]. התחרות היא של הכיתה נגד המודל, לא של זוג נגד זוג. כל נפילה היא ״ניצחון״ של הכיתה, והמדריך מדגים אותו בחיוך. בכיתות ג-ד אין מילים ״הטיה״ ו״מעקב״, אומרים ״הוא למד את הרקע״. המדריך אומר את הסיבה לכל נפילה בתוך 30 שניות מהחשיפה, ורק אז הכיתה כותבת. אחרי המשחק בוחרים נפילה אחת לתיקון במודול cd-fix-one-fall. מול הילדים אומרים ״המחשב״ ולא ״מודל״.

── סדר יום ──
• 7 ד׳ · כדור על דשא - בפעילות בלי מכשיר מאמנים חבר רק עם כרטיסי ״כדור על דשא״ ומראים לו דשא ריק. הוא אומר ״כדור״. למה?
• 13 ד׳ · משחק ההפלה - זוגות מביאים תרגיל להפלת המחשב של הכיתה (חפץ דומה, רקע חדש, חצי מוסתר) על שולחן ההפלה; המצלמה על השולחן בלבד. הכיתה סופרת כמה פעמים הפילה, המדריך אומר את הסיבה תוך 30 שניות, ורושמים ב״ספר הטעויות״.

── הערכה ──
ראיות: ספר הטעויות עם 6 שורות לפחות, ותשובה של כל זוג בכרטיסי כדור על דשא.
הושלם כאשר: הכיתה הפילה את המודל לפחות 5 פעמים וכתבה סיבה מנומקת ל-3 מהן.

── התאמות ──
קל יותר: המדריך מציע את הנפילות הראשונות והכיתה מנחשת למה.
מאתגר יותר: כל זוג מתכנן נפילה לפני שמנסה, ואחר כך משווה בין התחזית לתוצאה.$ws$, array[$ws$band:c-d$ws$, $ws$audience:school$ws$, $ws$level:L1$ws$, $ws$ai-mode:facilitator-device$ws$, $ws$background_trap$ws$, $ws$failure_by_design$ws$]::text[], true);
update public.ws_modules set title = $ws$כמה הוא בטוח? הפס והקו$ws$, summary = $ws$סדר יום: מסדרים בשורה (4 ד׳) · קו החלטה (5 ד׳) · ניחוש הביטחון (3 ד׳) · הפס החי (3 ד׳)$ws$, module_type = $ws$practice$ws$, pipeline_stage = $ws$evaluate$ws$, duration_minutes = 15, objectives = array[$ws$להבין שהמחשב אומר ״כמה הוא בטוח״ ולא רק תשובה.$ws$, $ws$לבחור מקום לקו החלטה ולראות מה קורה לטעויות כשמזיזים אותו.$ws$, $ws$לחבר בין הקו שלהם לפס הצבעוני של המחשב.$ws$]::text[], exercises = $ws$[{"title": "הקו שלנו", "instructions": "1. הקבוצה מניחה 12 כרטיסים בשורה על השולחן, מ״בטוח חתול״ בצד ימין עד ״בטוח לא חתול״ בצד שמאל.\n2. מניחים חוט בין שני כרטיסים: מימין הוא ״חתול״, משמאל ״לא חתול״.\n3. בודקים: איזה כרטיס הוא כלב שנכנס לצד החתולים? איזה חתול יצא החוצה?\n4. מזיזים את החוט כרטיס אחד ימינה ושמאלה ורושמים מה קרה לטעויות.", "kind": "group", "tool_hook": "none"}, {"title": "הפס החי", "instructions": "1. המדריך מניח 3 תמונות קשות מודפסות על שולחנו ומפעיל את המצלמה החיה על השולחן בלבד (לא על הכיתה).\n2. הכיתה מנבאת אם הפס יהיה ירוק, צהוב או אדום.\n3. משווים לחוט הקבוצתי ואומרים איפה היינו שמים את הקו אם מדובר בתמונת הסריקה של הספרייה.", "kind": "class", "tool_hook": "live_cam"}]$ws$::jsonb, materials = $ws$[{"label": "12 כרטיסי תמונה לכל קבוצה (חתולים, כלבים, ציורים מטושטשים, בלי אנשים)", "kind": "supply"}, {"label": "חוט או סרגל", "kind": "supply"}, {"label": "כרטיסי מספרים 1 עד 5", "kind": "supply"}, {"label": "מכשיר המדריך", "kind": "supply"}, {"label": "כרטיס הכנה ליריד לכל זוג (3 שורות להשלמה)", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקורות: [05 #19], [02 §2.2]. פס צבע ו״X מתוך 10״ בלבד, ללא אחוזים וללא המילה ״סף״ (threshold) בכיתות ג-ד. אם רוצים מונח, אומרים ״הקו שלנו״. בסיום ״הפס החי״ כל זוג ממלא כרטיס הכנה ליריד (דקה לזוג, או כשיעורי בית): ״לימדנו את המחשב לזהות ___. הוא נופל על ___. הנפילה הכי טובה שלנו הייתה ___.״

