   and (title, summary, module_type, pipeline_stage, duration_minutes, objectives, exercises, materials, facilitator_notes, tags, requires_app) is distinct from ($ws$יריד הכיתה: מה המחשב שלנו למד$ws$, $ws$סדר יום: הכנת תחנות (6 ד׳) · שני סבבי יריד (14 ד׳) · משפט ותעודה (6 ד׳) · סגירה (4 ד׳)$ws$, $ws$demo$ws$, $ws$demo$ws$, 30, array[$ws$להציג מה המחשב של הכיתה יודע ומה הוא עוד לא יודע.$ws$, $ws$לנסח משפט אחד: ״לימדנו את המחשב לזהות...״.$ws$, $ws$להשתתף בתחנות של כיתה מקבילה או של הורים.$ws$]::text[], $ws$[{"title": "תחנות היריד", "instructions": "1. המדריך מחלק לחמש תחנות: אלבום, ספר הטעויות, רובוט אנושי עם כרטיסים, ניחוש ביטחון, תחנה חיה של המדריך.\n2. קבוצה מציגה בתחנה במשך 7 דקות, ואחר כך מתחלפת עם קבוצה ביקורת.\n3. המבקרים מנסים להפיל את התחנה במבחן ההפלה שהזוג המציג הכין (חפץ דומה או רקע שונה); בתחנה החיה המצלמה על שולחן התחנה בלבד.\n4. כשנופל, המציגים לא מתנצלים: אומרים מה חסר באלבום. המדריך מנסח: ״עוד לא לימדנו אותו״.", "kind": "group", "tool_hook": "live_cam"}, {"title": "המשפט שלנו", "instructions": "1. כל זוג מקבל כרטיס עם שני משפטים להשלמה.\n2. משלימים את כרטיס ההכנה ממפגש 3: ״לימדנו את המחשב לזהות ___. הוא עוד לא מכיר ___. הנפילה הכי טובה שלנו הייתה ___.״\n3. המדריך מוסיף את המשפט לתעודה האישית של הזוג.", "kind": "group", "tool_hook": "none"}]$ws$::jsonb, $ws$[{"label": "5 שולחנות תחנה", "kind": "supply"}, {"label": "אלבומים וספר הטעויות מהמפגשים הקודמים", "kind": "supply"}, {"label": "כרטיסי רובוט אנושי", "kind": "supply"}, {"label": "מכשיר המדריך במצב תחנה חיה", "kind": "supply"}, {"label": "כרטיסי משפט", "kind": "supply"}, {"label": "תעודות מודפסות", "kind": "supply"}, {"label": "כרטיסי ההכנה ממפגש 3", "kind": "supply"}]$ws$::jsonb, $ws$מקורות: [02 §4 ג-ד], [06 §8]. הצגת הכיתה לכיתה מקבילה, ללא לקוח חיצוני. אם אין כיתה מקבילה מזמינים הורים או כיתה צעירה. בדיקת ה-post (assess-concept-check-cd) נעשית בתחילת המפגש, בכיתה שקטה, לפני היריד ולפני הרעש. כל זוג מגיע עם כרטיס ההכנה שמילא בסוף מפגש 3 ומתרגל אותו מול זוג שכן בהכנת התחנות. אין דירוג תוצאות ולא לפי ״כמה מתוך 10״, ״אין מקום ראשון״; תו הכרה לפי קריטריונים לכל זוג שעמד בהם. ילדים עם צמיד צבעוני לא מצולמים. בתחנה החיה המצלמה מופנית לשולחן ולחפצים בלבד, לא למבקרים. מול הילדים אומרים ״המחשב״ ולא ״מודל״.

