update public.ws_modules set title = $ws$בדיקת מושגים בתמונות: לפני ואחרי (ג-ד)$ws$, summary = $ws$סדר יום: הסבר (2 ד׳) · שבע שאלות (7 ד׳) · אסיפה (1 ד׳)$ws$, module_type = $ws$practice$ws$, pipeline_stage = null, duration_minutes = 10, objectives = array[$ws$למדוד התקדמות בשבעה רעיונות: מי מלמד, גיוון, רקע מטעה, בדיקה על חדש, ביטחון, ספירה ופרטיות.$ws$, $ws$לתת למדריך תמונה כיתתית של מה שהכיתה יודעת לפני ואחרי.$ws$, $ws$לעשות זאת בקריאה בקול ובכרטיסי צבע, בלי הקלדה.$ws$]::text[], exercises = $ws$[{"title": "שבע שאלות בתמונות", "instructions": "1. מחלקים דף עם שבע שורות, בכל שורה ארבע תמונות מסומנות A, B, C, D; האחרונה סימן שאלה: ״לא יודע/ת״.\n2. המדריך קורא שאלה ומחכה עד שכולם מקיפים תשובה. בלי עזרה ובלי רמזים.\n3. אוספים בקופסה. המדריך סופר כמה בחרו בכל אפשרות ומתעד בטבלה כיתתית.\n4. ב-post חושפים את התשובות לשתי השאלות הקשות ביותר ומדברים עליהן דקה.", "kind": "individual", "tool_hook": "none", "concept_check_id": "cc-cd", "questions": [{"q": "איזה אלבום ילמד את המחשב טוב יותר להכיר כוסות?", "options": ["20 תמונות של אותה כוס על אותו שולחן", "20 תמונות של כוסות שונות על רקעים שונים", "3 תמונות בלבד", "לא יודע/ת"], "answer": 1, "core": "variety", "image_brief": ["20 ריבועים זהים של כוס לבנה", "רשת של כוסות בצבעים וברקעים שונים", "שלוש תמונות", "סימן שאלה"], "id": "cd_variety"}, {"q": "ילד אימן מודל על 10 תמונות של כדור ובדק אותו על אותן 10 תמונות. המודל צדק ב-10 מתוך 10. האם הוא באמת יודע לזהות כדורים?", "options": ["כן, בטוח", "אולי: צריך לבדוק גם על תמונות חדשות", "לא, המחשב טועה", "לא יודע/ת"], "answer": 1, "core": "train_test", "image_brief": ["עשר תמונות כדור בשני סטים זהים", "שורה של תמונות חדשות עם סימן שאלה", "מחשב עם X", "סימן שאלה"], "id": "cd_test"}, {"q": "מודל ראה רק כלבים על דשא ורק זאבים בשלג. מראים כלב בשלג. מה הוא יגיד?", "options": ["כלב", "זאב", "לא יודע", "לא יודע/ת"], "answer": 1, "core": "bias", "image_brief": ["כלב על דשא", "זאב על שלג", "סימן שאלה", "סימן שאלה"], "id": "cd_bias"}, {"q": "הפס של המודל חצי צהוב וחצי ירוק. מה זה אומר?", "options": ["הוא בטוח לגמרי", "הוא לא בטוח", "המכשיר מקולקל", "לא יודע/ת"], "answer": 1, "image_brief": ["פס ירוק מלא", "פס חצי צהוב חצי ירוק", "מכשיר שבור", "סימן שאלה"], "id": "cd_confidence"}, {"q": "המודל החליט שדשא ריק הוא כדור. מה מוסיפים לאלבום?", "options": ["עוד כדורים בלבד", "תמונות דשא בלי כדור", "מוחקים הכול", "לא יודע/ת"], "answer": 1, "image_brief": ["כדור על דשא", "דשא ריק בלי כדור", "פח אשפה", "סימן שאלה"], "id": "cd_background"}, {"q": "מגדילים תמונה מאוד. מה רואים?", "options": ["ריבועים קטנים", "ציור צבוע", "מילים", "לא יודע/ת"], "answer": 0, "image_brief": ["רשת פיקסלים", "ציור צבעוני", "טקסט", "סימן שאלה"], "id": "cd_pixels"}, {"q": "רוצים להוסיף תמונה של חבר לאלבום. מה עושים?", "options": ["מוסיפים", "לא מוסיפים: בסדנה מצלמים רק חפצים", "מוסיפים אם הוא מסכים", "לא יודע/ת"], "answer": 1, "image_brief": ["ילד מצולם", "חפץ בלבד", "ילד מרים יד", "סימן שאלה"], "note": "התשובה הנכונה בסדנה היא תמיד חפצים בלבד, גם בהסכמה.", "id": "cd_privacy"}]}, {"title": "טבלת סיכום כיתתית", "instructions": "1. המדריך מכין טבלה עם שבע שורות ושלוש עמודות A, B, C.\n2. סופרים כמה ילדים בחרו בכל אפשרות בכל שאלה, בלי שמות.\n3. שומרים את הטבלה עם תאריך (pre או post).\n4. ב-post משווים את שתי הטבלאות ומציגים לכיתה שתי שאלות שבהן המספרים השתנו הכי הרבה.", "kind": "class", "tool_hook": "none"}]$ws$::jsonb, materials = $ws$[{"label": "דף שאלון מודפס (7 שורות) לכל ילד", "kind": "supply"}, {"label": "עיפרון", "kind": "supply"}, {"label": "קופסה לאיסוף", "kind": "supply"}, {"label": "מקרן להצגת התמונות", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$אותם פריטים ב-pre וב-post. בכל שאלה האפשרות האחרונה היא ״לא יודע/ת״ (באיור: סימן שאלה); מדווחים ספירות לפריט, אחוזים רק מ-15 משיבים. מקור: [06 §4.2]. אנונימי, ממוצעים כיתתיים בלבד. השאלות core (אימון ובדיקה, גיוון, הטיה) שקולות מבחינת המושג בכל הרצועות אך מנוסחות לגיל; משווים בתוך רצועה בלבד. לא מציגים אחוזים להורים כשהכיתה קטנה מ-15 משיבים, אלא ״X מתוך Y״ [06 §10].

