update public.ws_modules set title = $ws$מדריך תיוג או כאוס$ws$, summary = $ws$סדר יום: הכנה (3 ד׳) · תיוג (8 ד׳) · משווים (5 ד׳) · מדריך כיתתי (4 ד׳)$ws$, module_type = $ws$practice$ws$, pipeline_stage = $ws$tag$ws$, duration_minutes = 20, objectives = array[$ws$להבין שעקביות בתיוג חשובה כמו הכמות.$ws$, $ws$לכתוב מדריך תיוג של ארבע שורות.$ws$, $ws$לחשב כמה תיבות שתי קבוצות הסכימו עליהן.$ws$]::text[], exercises = $ws$[{"title": "תיוג עם מדריך ובלי", "instructions": "1. קבוצה א׳ מקבלת 10 תמונות בלי הנחיות. קבוצה ב׳ מקבלת מדריך: תיבה צמודה, כוללים חצי מוסתר, לא מסמנים אם נראה פחות מ-10 אחוזים, שם מחלקה אחיד.\n2. כל קבוצה מציירת תיבות בטוש על שקף שמונח על התמונה.\n3. מניחים את שני השקפים זה על זה על שולחן אור או חלון.\n4. סופרים תיבות שחופפות כמעט לגמרי לעומת תיבות שונות.", "kind": "group", "tool_hook": "none"}, {"title": "המדריך שלנו", "instructions": "1. הכיתה מסכמת מה הכי גרם לאי-הסכמה.\n2. כל קבוצה מציעה שורה אחת למדריך.\n3. בוחרים ארבע שורות ותולים על הקיר.", "kind": "class", "tool_hook": "none"}]$ws$::jsonb, materials = $ws$[{"label": "10 תמונות מודפסות או מוקרנות (חפצים, ללא אנשים)", "kind": "supply"}, {"label": "שקפים שקופים וטושים מחיקים", "kind": "supply"}, {"label": "שולחן אור או חלון", "kind": "supply"}, {"label": "כרטיס מדריך התיוג", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקור: [05 #25]. במעבדת ה-ו (מפגש 3) רץ אחרי הגשת האימון, בדקות 55-75, ללא מכשיר, בזמן שהאימון רץ. אפשר ללא מכשיר כדי לפנות טאבלטים. אם יש זמן, מתרגלים על תמונה עם שני חפצים חופפים.

── סדר יום ──
• 3 ד׳ · הכנה - שתי קבוצות מקבלות אותן 10 תמונות מודפסות או מוצגות במסך.
• 8 ד׳ · תיוג - קבוצה א׳ בלי הנחיות. קבוצה ב׳ עם מדריך של 4 שורות. מציירים תיבות בטוש על שקף שקוף.
• 5 ד׳ · משווים - מניחים שקפים זה על זה. סופרים אי-הסכמות.
• 4 ד׳ · מדריך כיתתי - כותבים יחד מדריך של 4 שורות.

── הערכה ──
ראיות: שני שקפים לכל קבוצה וספירת אי-הסכמה, ומדריך תיוג כיתתי תלוי.
הושלם כאשר: שתי הקבוצות השוו שקפים והכיתה כתבה מדריך של ארבע שורות.

── התאמות ──
קל יותר: המדריך מתייג את שתי התמונות הראשונות יחד עם הקבוצה.
