update public.ws_modules set title = $ws$ציון 1 עד 10 וגלריית מה הוא פספס$ws$, summary = $ws$סדר יום: רצועת המעטפה (5 ד׳) · ארבע המשבצות (8 ד׳) · גלריית מה הוא פספס (8 ד׳) · תוכנית תיקון (8 ד׳) · תיקון מהיר (6 ד׳)$ws$, module_type = $ws$practice$ws$, pipeline_stage = $ws$evaluate$ws$, duration_minutes = 35, objectives = array[$ws$לספור על 10 תמונות המעטפה: מצא, פספס, התריע סתם (״X מתוך 10 תמונות חדשות״), ורק אז לקרוא ציון 1 עד 10 ולהשוות לניבוי.$ws$, $ws$לסווג תמונות שהמודל פספס ולנסח השערה לכל כשל.$ws$, $ws$לתכנן ולצלם תיקון קטן ולהגיש סבב שני.$ws$]::text[], exercises = $ws$[{"title": "רצועת המעטפה וציון", "instructions": "1. כל שלישייה כותבת ניבוי: ״___ מתוך 10״.\n2. המדריך מראה לקבוצה רצועה של 10 תמונות המעטפה שלה, כל אחת מסומנת מצא / פספס / התריע סתם. סופרים בקול: ״מצא 6 מתוך 10 תמונות חדשות, פספס 3, התריע סתם 1״.\n3. רק אחר כך המדריך מראה את הציון 1 עד 10 לכל מחלקה, ופעם אחת גם את הציון על תמונות האימון לידו: למה הוא גבוה יותר?\n4. כותבים משפט אחד: ״המודל טוב ב___ ופחות ב___״.", "kind": "group", "tool_hook": "cloud_train"}, {"title": "ארבע המשבצות", "instructions": "1. מציירים טבלה 2 על 2 על פוסטר: צדק ומצא; פספס; התריע סתם; צדק שאין.\n2. ממלאים את המספרים מספירת הרצועה (10 תמונות המעטפה), לא מהדוח.\n3. שואלים: איזו משבצת מפחידה יותר ללקוח שלנו, ולמה?", "kind": "group", "tool_hook": "cloud_train"}, {"title": "גלריית מה הוא פספס", "instructions": "1. כל קבוצה מדביקה 3 תמונות פספוס על הקיר.\n2. קבוצות מסתובבות ומדביקות פתק ״למה לדעתנו?״ על כל תמונה.\n3. הקבוצה קוראת את הפתקים ומסמנת את ההשערה ההגיונית ביותר.\n4. מתכננים ורושמים 10 תמונות חדשות שיבדקו אותה.", "kind": "group", "tool_hook": "cloud_train"}]$ws$::jsonb, materials = $ws$[{"label": "מסך כיתה עם דוח התוצאות", "kind": "supply"}, {"label": "פוסטר ארבע משבצות לכל קבוצה", "kind": "supply"}, {"label": "פתקים", "kind": "supply"}, {"label": "הדפסות של 3 תמונות פספוס לקבוצה", "kind": "supply"}, {"label": "טאבלטים", "kind": "supply"}, {"label": "רצועה מודפסת של 10 תמונות המעטפה לכל קבוצה, מסומנות מצא / פספס / התריע סתם", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקורות: [02 §3 L2, §6], [06 §5], [05 #29]. קודם ספירה, אחר כך ציון: לכל קבוצה רצועה של 10 תמונות המעטפה שנחתמו במפגש 3, כל אחת מסומנת מצא / פספס / התריע סתם, והתוצאה נאמרת ״X מתוך 10 תמונות חדשות״. הציון 1 עד 10 נגזר מ-mAP בלי להגיד mAP ומוצג רק אחרי הספירה; פעם אחת מראים לידו את הציון על תמונות האימון כדי שיראו שהוא מנופח. הגלריה חשובה יותר מהמספר. אם אין גלריית פספוסים באפליקציה (requires_product: misses_gallery): המדריך מצלם מסך או מדפיס 3 תמונות פספוס לכל קבוצה, והגלריה היא על הקיר. מצב A (אימון בתוך המפגש הקודם): התוצאות מוכנות בפתיחה. מצב B (תור או אופליין): המדריך הגיש בסוף מפגש 3 והתוצאות מגיעות לפני המפגש. אין לוח דירוג בין קבוצות [08 §9].

