update public.ws_modules set title = $ws$יריד: מנסים להפיל את המודלים של האחרים$ws$, summary = $ws$סדר יום: הכנת תחנות (5 ד׳) · סבב 1 (10 ד׳) · סבב 2 (10 ד׳) · מה למדנו מהנפילה (5 ד׳) · משפט ותעודות (5 ד׳)$ws$, module_type = $ws$demo$ws$, pipeline_stage = $ws$demo$ws$, duration_minutes = 35, objectives = array[$ws$להציג מודל ולהסביר מה למדנו מהנפילות.$ws$, $ws$לנסות להפיל את המודל של קבוצה אחרת בצורה מכבדת.$ws$, $ws$לסכם במשפט אחד מה המודל יודע ומה לא.$ws$]::text[], exercises = $ws$[{"title": "תחנה והפלה", "instructions": "1. הקבוצה מציגה את המודל במצב הדגמה (המצלמה חיה, מופנית לשולחן התחנה ולחפצים בלבד, ולא שומרת פריימים) ומספרת על הלקוח, על המשימה ועל ״X מתוך 10 תמונות חדשות״ שלה.\n2. הקבוצה המציגה מכינה מראש ״מבחן הפלה״ אחד שהיא שולטת בו (חפץ דומה, רקע שונה או תאורה אחרת); הקבוצה המבקרת מנסה אותו.\n3. אם המודל נפל, המציגים אומרים ״תודה, זה שיעור״, המדריך מנסח ״עוד לא לימדנו אותו״, ומתעדים בספר הטעויות.\n4. ממשיכים ליותר מ-3 ניסיונות או עד סוף הסבב.", "kind": "group", "tool_hook": "live_cam"}, {"title": "מה למדנו מהנפילה", "instructions": "1. כל קבוצה כותבת משפט על הנפילה הכי מעניינת.\n2. מוסיפים שורה: ״כדי לתקן היינו מוסיפים ___״.\n3. הלקוח או האורח קוראים משפט אחד מכל קבוצה.", "kind": "group", "tool_hook": "presentation"}]$ws$::jsonb, materials = $ws$[{"label": "טאבלט נעול בשליטת מורה לכל קבוצה", "kind": "supply"}, {"label": "ספר טעויות ופוסטר 4 משבצות", "kind": "supply"}, {"label": "תעודות מודפסות", "kind": "supply"}, {"label": "מקרן", "kind": "supply"}, {"label": "אורח (הלקוח, מורה או הורים)", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקורות: [02 §4 ה-ו], [08 §9], [10 §8]. אין דירוג בין קבוצות, לא לפי ציון ולא לפי דיוק; הציון נשאר בתוך הקבוצה ולא מוקרא בקול. תגי הכרה לפי קריטריונים שהוצגו במפגש 1, לכל קבוצה שעמדה בהם: ״הדאטה המגוון״, ״הנפילה הכי מעניינת״, ״ההסבר הברור״. ילדים לא מוצגים על הבמה בכוח. מצב הדגמה לא שומר פריימים. המצלמה בתחנה מופנית לשולחן ולחפצים, לא לאורחים ולא לילדים. אורחים לא מצלמים ילדים של אחרים. אחרי היריד מבצעים post.

