   and (title, summary, module_type, pipeline_stage, duration_minutes, objectives, exercises, materials, facilitator_notes, tags, requires_app) is distinct from ($ws$יום חווייתי ה-ו: יריד מודלים ותעודות$ws$, $ws$סדר יום: הקמה (5 ד׳) · יריד (20 ד׳) · משפט והסקת מסקנות (10 ד׳) · בדיקת סיום (5 ד׳) · תעודות וסיום (5 ד׳)$ws$, $ws$demo$ws$, $ws$demo$ws$, 45, array[$ws$להציג מודל ולבדוק אותו מול ניסיונות הפלה.$ws$, $ws$לכתוב משפט אחד על מה המודל יודע ומה לא.$ws$, $ws$לקבל תעודה ולסגור עם post.$ws$]::text[], $ws$[{"title": "יריד קצר", "instructions": "1. הקבוצה מציגה את הלקוח, המשימה והציון.\n2. קבוצה ביקורת מנסה להפיל עם 3 ניסיונות.\n3. מתחלפים.", "kind": "group", "tool_hook": "live_cam"}, {"title": "המשפט שלנו", "instructions": "1. כותבים: ״המודל שלנו מזהה ___ ב-X מתוך 10 תמונות חדשות. הוא עדיין מתקשה ב___.״\n2. מקריאים משפט אחד מכל קבוצה.", "kind": "group", "tool_hook": "presentation"}]$ws$::jsonb, $ws$[{"label": "תחנות", "kind": "supply"}, {"label": "פוסטר 4 משבצות", "kind": "supply"}, {"label": "תעודות", "kind": "supply"}, {"label": "דפי שאלון סיום", "kind": "supply"}]$ws$::jsonb, $ws$מקור: [10 §8]. מיועד לסגירת יום חווייתי. הגרסה הקצרה של ef-fair-booths. אין דירוג, לא לפי דיוק ולא לפי ציון; כל פספוס מנוסח ״עוד לא לימדנו אותו״. המצלמה בתחנה מופנית לחפצים בלבד.

── סדר יום ──
• 5 ד׳ · הקמה - כל קבוצה מקימה תחנה עם מודל סבב 2 ופוסטר.
• 20 ד׳ · יריד - שני סבבים של 10 דקות. מציגים ומנסים להפיל.
• 10 ד׳ · משפט והסקת מסקנות - כל קבוצה כותבת משפט למה המודל טוב ופחות טוב.
• 5 ד׳ · בדיקת סיום - אם ה-post המלא (assess-concept-check-ef) רץ כמודול נפרד אחרי היריד, משתמשים בזמן למעגל ״מה אקח הביתה״; אחרת גרסה מקוצרת של שלוש שאלות core.
• 5 ד׳ · תעודות וסיום - תעודות ומעגל סיום.

── הערכה ──
ראיות: משפט המודל בכל קבוצה ו-post של הכיתה.
הושלם כאשר: כל קבוצה הציגה פעם אחת וביקרה בתחנה אחת ופוסט הושלם.

── התאמות ──
קל יותר: המציגים מקריאים את המשפט בלבד.
מאתגר יותר: המציגים מוסיפים ״מה היינו עושים עם עוד שבוע״.$ws$, array[$ws$band:e-f$ws$, $ws$audience:school$ws$, $ws$level:L2$ws$, $ws$ai-mode:teacher-controlled$ws$, $ws$hackathon$ws$, $ws$half_day$ws$]::text[], true);
update public.ws_modules set title = $ws$בדיקת מושגים: לפני ואחרי (ה-ו)$ws$, summary = $ws$סדר יום: הסבר (2 ד׳) · שמונה שאלות (7 ד׳) · אסיפה (1 ד׳)$ws$, module_type = $ws$practice$ws$, pipeline_stage = null, duration_minutes = 10, objectives = array[$ws$למדוד התקדמות בשמונה מושגים: אימון ובדיקה, גיוון, הטיה, ביטחון, טבלת ארבע המשבצות, תיבה, עלות טעות ופרטיות.$ws$, $ws$לזהות פערים לפני מפגשי הדאטה.$ws$, $ws$לתת גם מדד גישה (ביטחון עצמי) כפריט אחרון.$ws$]::text[], exercises = $ws$[{"title": "שמונה שאלות", "instructions": "1. מחלקים דף בן שמונה שאלות עם תמונות קטנות ליד כל אפשרות.\n2. הילדים עונים לבד בשקט. המדריך קורא שאלה בקול רק אם ילד מבקש.\n3. המדריך מחשב ממוצעים כיתתיים בלבד ושומר את הדפים עד ה-post.\n4. ב-post מוסיפים שאלה פתוחה אחת: ״הסבירו במשפט למה מודל שנבדק על תמונות שאימנו עליו מטעה״.", "kind": "individual", "tool_hook": "none", "concept_check_id": "cc-ef", "questions": [{"q": "למה בודקים את המודל על תמונות שלא היו באימון?", "options": ["כדי לחסוך זמן", "כדי לדעת אם הוא יזהה גם דברים חדשים", "כדי שהאימון יהיה מדויק יותר", "לא יודע/ת"], "answer": 1, "core": "train_test", "id": "ef_test"}, {"q": "מה יעזור הכי הרבה למודל שמזהה בקבוקים בחצר?", "options": ["100 תמונות של אותו בקבוק באותה פינה", "50 תמונות ברקעים, בשעות ובמרחקים שונים", "10 תמונות מטושטשות", "לא יודע/ת"], "answer": 1, "core": "variety", "id": "ef_variety"}, {"q": "כל תמונות האימון של מחלקה אחת צולמו בחלון בבוקר. מה הכי סביר שיקרה בצהריים בחדר חשוך?", "options": ["המודל יזהה בלי בעיה", "המודל עלול לטעות כי לא ראה תנאים כאלה", "המודל ילמד לבד", "לא יודע/ת"], "answer": 1, "core": "bias", "id": "ef_bias"}, {"q": "מודל אומר ״בקבוק״ ופס הביטחון ירוק. האם הוא בטח צודק?", "options": ["כן", "לא בהכרח: בטוח איננו הוכחה", "רק בלילה", "לא יודע/ת"], "answer": 1, "id": "ef_confidence"}, {"q": "במשבצת ״התריע סתם״ נכתב 6. מה זה אומר?", "options": ["המודל פספס 6 חפצים", "המודל סימן 6 דברים שלא היו חפצים", "6 חפצים זוהו נכון", "לא יודע/ת"], "answer": 1, "id": "ef_four"}, {"q": "מה תיבה סביב חפץ מוסיפה על תווית בלבד?", "options": ["צבע", "איפה החפץ נמצא", "גודל הקובץ", "לא יודע/ת"], "answer": 1, "id": "ef_box"}, {"q": "בחדר אוכל המודל סופר לחמניות. מה חמור יותר?", "options": ["שיפספס כמה לחמניות", "שיתריע על לחמניות שאינן", "אין הבדל", "תלוי מה הלקוח עושה עם המספר", "לא יודע/ת"], "answer": 3, "id": "ef_cost"}, {"q": "ילד מצלם בטעות חבר ליד השולחן. מה הצעד הנכון?", "options": ["משאירים", "מוחקים מיד ומדווחים למדריך", "שולחים לחבר", "לא יודע/ת"], "answer": 1, "id": "ef_privacy"}, {"q": "אני בטוח/ה שאני יכול/ה להסביר לחבר איך מאמנים מודל זיהוי (1 עד 5)", "options": ["1", "2", "3", "4", "5"], "answer": null, "note": "שאלת ביטחון עצמי או גישה, ללא תשובה נכונה."}, {"q": "אני רוצה להמשיך ללמוד על זה (1 עד 5)", "options": ["1", "2", "3", "4", "5"], "answer": null, "note": "שאלת ביטחון עצמי או גישה, ללא תשובה נכונה."}]}, {"title": "טבלת סיכום כיתתית", "instructions": "1. המדריך מכין טבלה עם שמונה שורות ועמודה לכל אפשרות.\n2. מחשבים לכל שאלה כמה ילדים ענו נכון (X מתוך Y), ואת ממוצע פריט הגישה.\n3. שומרים בנפרד את pre ואת post, בלי שמות.\n4. ב-post משווים ומציגים לכיתה את שלוש שאלות ה-core.", "kind": "class", "tool_hook": "none"}]$ws$::jsonb, materials = $ws$[{"label": "דף שאלון (8 שאלות) לכל ילד", "kind": "supply"}, {"label": "עיפרון", "kind": "supply"}, {"label": "קופסה לאיסוף", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$אותם פריטים ב-pre וב-post. בכל שאלה האפשרות האחרונה היא ״לא יודע/ת״ (באיור: סימן שאלה); מדווחים ספירות לפריט, אחוזים רק מ-15 משיבים. מקור: [06 §4.3]. שלוש שאלות core שקולות מבחינת המושג לשכבות האחרות (בניסוח לגיל). פריט הגישה (ביטחון עצמי) מדווח בנפרד. אין דיווח באחוזים כשהכיתה קטנה מ-15 משיבים [06 §10].

── סדר יום ──
• 2 ד׳ · הסבר - בדיקה אנונימית, אין ציון, אותה בדיקה בתחילת הסדנה ובסופה.
• 7 ד׳ · שמונה שאלות - מענה בכתב על נייר או בטאבלט נעול של בית הספר. פריט אחרון: סולם 1 עד 5.
• 1 ד׳ · אסיפה - אוספים את הדפים או סוגרים את הטופס. בלי שמות.

