update public.ws_modules set title = $ws$מתחזים, רקעים ריקים והיפוך שמשבש תוויות$ws$, summary = $ws$סדר יום: פתיחה (5 ד׳) · המתחזים (15 ד׳) · ציד רקעים ריקים (15 ד׳) · היפוך שובר תווית (10 ד׳)$ws$, module_type = $ws$practice$ws$, pipeline_stage = $ws$evaluate$ws$, duration_minutes = 45, objectives = array[$ws$להוכיח ש״דוגמאות שליליות קשות״ מורידות אזעקות שווא.$ws$, $ws$לצלם רקעים ריקים ולבדוק אזעקות שווא בזיהוי חי.$ws$, $ws$לקבוע אילו אוגמנטציות אסורות לפרויקט (היפוך שמשנה תווית).$ws$]::text[], exercises = $ws$[{"title": "המתחזים", "instructions": "1. מאמנים במאמן הכיס מחלקה אחת על חפץ אחד (למשל קלמר) עם 20 תמונות.\n2. כל זוג מביא 5 ״מתחזים״ דומים בצורה או בצבע. מפעילים ומספרים אזעקות שווא.\n3. מצלמים את המתחזים כמחלקת ״לא קלמר״ ומאמנים שוב.\n4. משווים: כמה אזעקות לפני ואחרי?", "kind": "group", "tool_hook": "pocket_trainer"}, {"title": "ציד רקעים ריקים", "instructions": "1. מצלמים 30 תמונות של המקומות שבהם המשימה מתרחשת, בלי החפץ.\n2. מאמנים עם הרקעים כמחלקת רקע, ובלעדיהם.\n3. מפעילים מצלמה חיה על רקע ריק במשך דקה ומסמנים כל אזעקת שווא.\n4. רושמים בטבלה: ללא רקעים / עם רקעים.", "kind": "group", "tool_hook": "series_capture"}, {"title": "היפוך שובר תווית", "instructions": "1. מאמנים ״חץ שמאלה״ ו״חץ ימינה״ בעזרת חץ מנייר.\n2. מראים חץ בתמונת מראה. המודל אומר את ההפך.\n3. הקבוצה בודקת את המחלקות שלה: אילו מחלקות משנות משמעות בהיפוך?\n4. כותבת שורה אחת בכרטיס המשימה: ״אין להפוך את ___״.", "kind": "group", "tool_hook": "pocket_trainer"}]$ws$::jsonb, materials = $ws$[{"label": "מאמן הכיס על טאבלט או מחשב של בית הספר (טלפון אישי רק בשיעור ייעודי באישור המנהל בכתב)", "kind": "supply"}, {"label": "5 מתחזים לכל זוג", "kind": "supply"}, {"label": "נייר לחץ", "kind": "supply"}, {"label": "טבלת אזעקות שווא", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקורות: [05 #30, #36, #39], [03 §2 פרק 8 סיווג]. מודול אופציונלי לסדנה ז-ט, מומלץ אחרי מפגש 4 או 5. דורש שהקבוצה כבר יודעת להפעיל מאמן הכיס (מפגש 1). סדר העבודה בכיתות ז-ט: הקבוצה משערת למה המודל נפל ומצלמת תיקון לפני שהמדריך מסביר. תוצאות כספירה (״X אזעקות שווא מתוך 30 תמונות רקע״) לפני כל אחוז. המצלמה מופנית לחפצים ולרקעים, לא לתלמידים.

── סדר יום ──
• 5 ד׳ · פתיחה - מראים קלמר מול לא קלמר: מודל בינארי שמבלבל בין חפצים דומים.
• 15 ד׳ · המתחזים - כל זוג מאמן מחלקה אחת על חפץ אחד, מביא 5 מתחזים, סופר אזעקות שווא, מוסיף אותם כמחלקת ״לא״ ובודק שוב.
• 15 ד׳ · ציד רקעים ריקים - מצלמים 30 תמונות של מקומות שבהם החפץ אמור להופיע בלי החפץ, מאמנים עם ובלי, ומפעילים מצלמה חיה על רקע ריק.
• 10 ד׳ · היפוך שובר תווית - מאמנים ״חץ שמאלה / חץ ימינה״, מציגים תמונת מראה ורושמים אילו מחלקות בפרויקט אסור להפוך.

── הערכה ──
