update public.ws_modules set title = $ws$טבלת בלבול בפתקים ועלות הטעות$ws$, summary = $ws$סדר יום: הכנה (5 ד׳) · הטבלה בפתקים (15 ד׳) · עלות הטעות (10 ד׳) · פרוסות (10 ד׳) · משפט לשקף (5 ד׳)$ws$, module_type = $ws$mixed$ws$, pipeline_stage = $ws$evaluate$ws$, duration_minutes = 45, objectives = array[$ws$לבנות טבלת בלבול 2 על 2 ולהבין שפספוס ואזעקת שווא הם שני סוגי טעות.$ws$, $ws$לקבוע איזו טעות יקרה יותר ללקוח של הקבוצה.$ws$, $ws$להסביר שדיוק ממוצע יכול להסתיר פרוסות חלשות.$ws$]::text[], exercises = $ws$[{"title": "הטבלה בפתקים", "instructions": "1. מציירים על הלוח טבלה 2 על 2: ״אמת: יש / אין״ מול ״המודל: אמר יש / אמר אין״.\n2. חבר (המודל) מקבל תמונה בלי לראות את התווית ואומר יש או אין.\n3. הקבוצה מדביקה פתק במשבצת: צדק ומצא, פספס, התריע סתם, צדק שאין.\n4. סופרים בכל משבצת ואומרים קודם כספירה: ״מצא X מתוך 20 תמונות חדשות, פספס Y, התריע סתם Z״. אחוז רק אחרי הספירה.", "kind": "group", "tool_hook": "none"}, {"title": "עלות הטעות", "instructions": "1. כל קבוצה כותבת למי יש עלות בכל משבצת (לקוח, נפגע, כסף, זמן).\n2. מסמנת איזה סוג טעות מפחיד יותר בלקוח שלה.\n3. מנסחת: ״אנחנו מעדיפים ___ מ___ כי ___״.\n4. מוסיפה את זה לכרטיס המשימה.", "kind": "group", "tool_hook": "none"}, {"title": "פרוסות", "instructions": "1. מוסיפים לכל תמונה תנאי: תאורה חזקה או חלשה, מרחק קרוב או רחוק.\n2. מחשבים את שיעור הצדק לכל פרוסה.\n3. מסמנים את הפרוסה החלשה ומציעים 10 תמונות לצלם בה.", "kind": "group", "tool_hook": "cloud_train"}]$ws$::jsonb, materials = $ws$[{"label": "לוח וטבלה 2 על 2", "kind": "supply"}, {"label": "פתקים בשני צבעים", "kind": "supply"}, {"label": "20 תמונות עם תווית אמת לכל קבוצה (ללא אנשים)", "kind": "supply"}, {"label": "תוצאות מהמודל (class_stats)", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקורות: [05 #31, #33], [06 §5 ז-ט], [08 §5]. עיקרון Gender Shades מיושם על תנאי החפץ ולא על אנשים: ״ביצועים ממוצעים מסתירים כשלים בפרוסות״. לא מציגים תמונות פנים. הקבוצה משערת את סיבת הפרוסה החלשה לפני שהמדריך מסביר. המודול מחליף את ״עלות טעות״ הקיימת במפגש 6 אם הקבוצה כבר ערכה אותה ומקדים אותה אם לא.

── סדר יום ──
• 5 ד׳ · הכנה - כל קבוצה מקבלת 20 תמונות עם תווית אמת ולוח עם טבלה 2 על 2.
• 15 ד׳ · הטבלה בפתקים - חבר משמש כמודל ומנבא כל תמונה. מדביקים פתק במשבצת הנכונה.
• 10 ד׳ · עלות הטעות - לכל משבצת: מי משלם? כותבים ללקוח משפט על מה הוא מעדיף, פספוס או אזעקה.
• 10 ד׳ · פרוסות - מחלקים את 20 התמונות לפי תנאי (תאורה או מרחק) ובודקים אם הדיוק שונה.
• 5 ד׳ · משפט לשקף - כותבים משפט אחד שייכנס לשקף של Demo Day.

── הערכה ──
ראיות: טבלת בלבול מלאה, משפט עלות וטבלת פרוסות.
הושלם כאשר: כל קבוצה מילאה 20 פתקים, כתבה איזו טעות יקרה יותר, ומצאה פרוסה חלשה.

── התאמות ──
קל יותר: 10 תמונות בלבד וטבלה מוכנה.
מאתגר יותר: מחשבים precision ו-recall לפי הטבלה (בכתב, עם סעיף הסבר במילים).$ws$, tags = array[$ws$band:g-i$ws$, $ws$audience:school$ws$, $ws$level:L3$ws$, $ws$optional$ws$, $ws$ai-mode:independent$ws$, $ws$confusion_matrix$ws$, $ws$error_cost$ws$, $ws$metric:precision-recall-in-words$ws$]::text[], requires_app = true, version = version + 1, updated_at = now()
