update public.ws_modules set title = $ws$בדיקת מושגים מקצועית: לפני ואחרי (י-יב)$ws$, summary = $ws$סדר יום: הסבר (2 ד׳) · שמונה שאלות (7 ד׳) · אסיפה (1 ד׳)$ws$, module_type = $ws$practice$ws$, pipeline_stage = null, duration_minutes = 10, objectives = array[$ws$למדוד התקדמות במושגי הערכה כמותיים: precision, recall, טבלת בלבול, סף ביטחון ופרוסות.$ws$, $ws$לבדוק זיהוי הטיה ופיצול נתונים נכון.$ws$, $ws$לעשות זאת בעשר דקות, עם מחשבון.$ws$]::text[], exercises = $ws$[{"title": "שמונה שאלות", "instructions": "1. הנבחנים מקבלים 8 שאלות, שתיים מהן חישוב.\n2. מענה עצמאי, מחשבון מותר.\n3. המדריך מחשב ממוצע כיתתי ושיעור שיפור בשלוש שאלות core (אימון ובדיקה, גיוון, הטיה).\n4. ב-post מוסיפים שאלה פתוחה אחת: ״הסבירו למה מודל נבחן על תמונות מאותה סדרת צילום מטעה״.", "kind": "individual", "tool_hook": "none", "concept_check_id": "cc-jl", "questions": [{"q": "קבוצה צילמה 300 תמונות ברצף באותו חדר וחילקה אקראית 80 אחוז לאימון ו-20 אחוז לבדיקה. בבדיקה היא קיבלה 98 אחוז. למה זה מטעה?", "options": ["כי תמונות כמעט זהות מאותה סדרה נמצאות גם באימון וגם בבדיקה", "כי 98 הוא מספר גבוה מדי תמיד", "כי 20 אחוז זה קטן מדי", "לא יודע/ת"], "answer": 0, "core": "train_test", "id": "jl_test"}, {"q": "המצלמה של הלקוח מופעלת ביום ובלילה בתעלה. איזה דאטה מתאים ביותר?", "options": ["500 תמונות ביום בלבד", "250 ביום ו-250 בלילה עם שינוי מרחק וזווית", "500 תמונות כולן מזווית אחת בשעת צהריים", "לא יודע/ת"], "answer": 1, "core": "variety", "id": "jl_variety"}, {"q": "מודל זיהה אפודים צהובים ב-95 אחוז ואפודים כתומים ב-60 אחוז. מה הסבר סביר ראשון?", "options": ["המודל מעדיף צהוב", "בדאטה היו מעט אפודים כתומים", "הלקוח התבלבל", "לא יודע/ת"], "answer": 1, "core": "bias", "id": "jl_bias"}, {"q": "בסט הבדיקה: 40 חפצים זוהו נכון, 10 אזעקות שווא ו-20 חפצים אמיתיים פוספסו. מה precision ו-recall?", "options": ["precision 0.80 ו-recall 0.67", "precision 0.67 ו-recall 0.80", "precision 0.80 ו-recall 0.80", "precision 0.50 ו-recall 0.67", "לא יודע/ת"], "answer": 0, "id": "jl_pr"}, {"q": "בטבלת בלבול מופיע 18 במשבצת ״אמת: בקבוק, ניבוי: פחית״. מה זה אומר?", "options": ["המודל טוב בבקבוקים", "המודל מבלבל בקבוק עם פחית", "יש יותר מדי בקבוקים בדאטה", "לא יודע/ת"], "answer": 1, "id": "jl_cm"}, {"q": "מפעל חייב לא להחמיץ מוצר פגום וצוות יבדוק אזעקות ידנית. מה עושים בסף הביטחון?", "options": ["מעלים אותו", "מורידים אותו", "משאירים כמו שהוא", "לא יודע/ת"], "answer": 1, "id": "jl_threshold"}, {"q": "דיוק כולל 92 אחוז. בתמונות לילה 60 אחוז. מה נכון?", "options": ["המודל מצוין", "צריך לבדוק פרוסות ולצלם עוד בלילה", "אין חשיבות לפרוסה", "לא יודע/ת"], "answer": 1, "id": "jl_slice"}, {"q": "מה מודד mAP50?", "options": ["ממוצע דיוק כשחפיפת התיבות עם תיבת האמת היא לפחות 50 אחוז", "אחוז התמונות שנבדקו", "מהירות ההסקה", "לא יודע/ת"], "answer": 0, "id": "jl_map"}, {"q": "מעניין אותי ללמוד עוד על ראייה ממוחשבת (1 עד 5)", "options": ["1", "2", "3", "4", "5"], "answer": null, "note": "שאלת ביטחון עצמי או גישה, ללא תשובה נכונה."}, {"q": "אני מרגיש/ה שאני יכול/ה לבנות כזה מודל לבד (1 עד 5)", "options": ["1", "2", "3", "4", "5"], "answer": null, "note": "שאלת ביטחון עצמי או גישה, ללא תשובה נכונה."}, {"q": "בינה מלאכותית היא גם בשבילי (1 עד 5)", "options": ["1", "2", "3", "4", "5"], "answer": null, "note": "שאלת ביטחון עצמי או גישה, ללא תשובה נכונה."}]}, {"title": "טבלת סיכום ושיפור", "instructions": "1. מחשבים לכל שאלה את שיעור הנכונות הכיתתי (X מתוך Y).\n2. מחשבים שיפור בשלוש שאלות core בין pre ל-post.\n3. מדווחים ממוצעים בלבד. לא מדווחים אחוזים אם יש פחות מ-15 משיבים.", "kind": "class", "tool_hook": "none"}]$ws$::jsonb, materials = $ws$[{"label": "דף שאלון (8 שאלות)", "kind": "supply"}, {"label": "מחשבון", "kind": "supply"}, {"label": "קופסה לאיסוף", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$אותם פריטים ב-pre וב-post. בכל שאלה האפשרות האחרונה היא ״לא יודע/ת״ (באיור: סימן שאלה); מדווחים ספירות לפריט, אחוזים רק מ-15 משיבים. מקורות: [06 §4.5, §6]. אפשר להוסיף 3 פריטי גישה מ-AILQ בסולם 1 עד 5 [06 §4.4]. אנונימי, ממוצעים בלבד, אין דיווח באחוזים מתחת ל-15 משיבים.

