update public.ws_modules set title = $ws$הערכה וחבילת ראיות: רובריקה, pre/post ו-30 יום$ws$, summary = $ws$סדר יום: מה מוכיחים ולמי (20 ד׳) · רובריקה וקריאה (30 ד׳) · חבילת ראיות (25 ד׳) · איסורים (15 ד׳)$ws$, module_type = $ws$practice$ws$, pipeline_stage = $ws$evaluate$ws$, duration_minutes = 90, objectives = array[$ws$להריץ pre/post אנונימי ולהפיק חבילת ראיות של עמוד אחד.$ws$, $ws$להשתמש ברובריקה של שכבת הגיל ובנוסח קריא לילד.$ws$, $ws$לתכנן מעקב 30 יום (Kirkpatrick 3).$ws$]::text[], exercises = $ws$[{"title": "רובריקה על הקלטה", "instructions": "1. צופים בהקלטה של 5 דקות של קבוצה.\n2. כל מורה ממלא את הרובריקה לבד ואז משווה עם חבר.\n3. מחשבים את ההפרש, מסמנים בעיות ניסוח ומתקנים.\n4. מסכמים: איזה קריטריון קשה לסימון?", "kind": "group", "tool_hook": "presentation"}, {"title": "חבילת ראיות", "instructions": "1. ממלאים 10 סעיפים של התבנית מנתונים אמיתיים או דמה.\n2. מסמנים אילו סעיפים נוצרים אוטומטית ואילו צריך להזין ידנית (לקוח, 30 יום).\n3. מכינים שורת מעקב ל-30 יום: כמה תלמידים פתחו שוב את המודל.", "kind": "individual", "tool_hook": "none"}]$ws$::jsonb, materials = $ws$[{"label": "דף ראיות (תבנית)", "kind": "supply"}, {"label": "רובריקות לפי שכבה", "kind": "supply"}, {"label": "הקלטה קצרה של קבוצה", "kind": "supply"}, {"label": "טבלת pre/post", "kind": "supply"}]$ws$::jsonb, facilitator_notes = $ws$מקורות: [06 §7, §9, §10]. הצטיינות לפי קריטריונים שמוצגים ביום הראשון (סט בדיקה הופרד, ספר טעויות מלא, דאטה מגוון, כנות על כשלים), בלי מכסה ובלי דירוג לפי דיוק; היא קבוצתית אך מותנית ברפלקציה אישית. ספירות לפריט תמיד (״4 מתוך 12 לפני, 9 מתוך 12 אחרי״), אחוזים רק מ-15 משיבים. הרובריקה מעריכה קבוצה, לא תלמיד.

── סדר יום ──
• 20 ד׳ · מה מוכיחים ולמי - מנהל, ראש עיר, הורים: מה כל אחד רוצה לראות (Kirkpatrick 1 עד 4).
• 30 ד׳ · רובריקה וקריאה - מפעילים רובריקה על Demo Day מוקלט ומשווים ציונים בין שני מעריכים.
• 25 ד׳ · חבילת ראיות - ממלאים תבנית של עמוד אחד מנתוני הסדנה של המורה.
• 15 ד׳ · איסורים - אין ציון אישי, אין דירוג בין בתי ספר, אין אחוזים מתחת ל-15 משיבים, אין דירוג לפי דיוק ביריד, אין מכסה להצטיינות.

── הערכה ──
ראיות: חבילת ראיות ממולאת ורובריקה מושווית.
הושלם כאשר: כל מורה מילא חבילה אחת ורובריקה על הקלטה בעקביות של לפחות 4 מתוך 6 קריטריונים עם חבר.

── התאמות ──
