insert into public.ws_modules (slug, title, summary, module_type, pipeline_stage, duration_minutes, objectives, exercises, materials, facilitator_notes, tags, requires_app) values ($ws$cd-fix-one-fall$ws$, $ws$מתקנים נפילה אחת$ws$, $ws$סדר יום: בוחרים נפילה (2 ד׳) · 10 תמונות תיקון (4 ד׳) · המדריך מלמד שוב ובודקים (4 ד׳)$ws$, $ws$practice$ws$, $ws$train$ws$, 10, array[$ws$לסגור את המעגל: נפילה, תמונות תיקון, לימוד מחדש ובדיקה חוזרת על אותו חפץ.$ws$, $ws$לנבא לפני הבדיקה החוזרת אם המחשב עדיין ייפול.$ws$, $ws$למלא את העמודה ״התיקון עבד?״ בספר הטעויות.$ws$]::text[], $ws$[{"title": "בוחרים נפילה", "instructions": "1. המדריך מקריא את ספר הטעויות. הכיתה מצביעה בכרטיסים (עיגול ירוק ״כן״) על הנפילה שחזרה הכי הרבה, למשל ״בד אדום״.\n2. המדריך אומר: ״מצאנו את החור. עכשיו מאכילים אותו.״\n3. שלושה זוגות מתנדבים לצלם.", "kind": "class", "tool_hook": "none"}, {"title": "10 תמונות תיקון", "instructions": "1. שלושת הזוגות מצלמים יחד 10 תמונות של החפץ שנפל על הרקע שהפיל אותו (למשל מחק על בד אדום), בטאבלט במצב צילום בלבד.\n2. הכלל נשאר: הידיים מאחורי הגב, רק החפץ בתמונה.\n3. שאר הכיתה מנבאת בכרטיסים: אחרי 10 תמונות, הוא עדיין ייפול?", "kind": "group", "tool_hook": "series_capture"}, {"title": "מלמדים שוב ובודקים", "instructions": "1. המדריך מוסיף את 10 התמונות ולוחץ ״למד״ בזמן שהכיתה סופרת בקול עד 30.\n2. בודקים את אותו חפץ על אותו רקע במצלמה החיה על שולחן המדריך.\n3. עמד? כותבים ״כן״ בעמודה ״התיקון עבד?״ בספר הטעויות. נפל? כותבים ״לא״ ומה נצלם בפעם הבאה.\n4. המשפט לסיום: ״המחשב יודע רק מה שהראינו לו, ועכשיו הראינו לו אדום.״", "kind": "class", "tool_hook": "live_cam"}]$ws$::jsonb, $ws$[{"label": "מכשיר המדריך עם המחשב מהמפגש הקודם", "kind": "supply"}, {"label": "טאבלט אחד במצב צילום בלבד", "kind": "supply"}, {"label": "ספר הטעויות עם העמודה ״התיקון עבד?״", "kind": "supply"}, {"label": "הרקע שהפיל (למשל בד אדום)", "kind": "supply"}]$ws$::jsonb, $ws$מקורות: ממצאי r2 (Hitron 2019: תיוג ובדיקה יחד; Tedre ו-Vartiainen 2021: לבדוק, להסביר, לשפר). ממלא את 10 הדקות הפנויות של מפגש 3 בין משחק ההפלה לפס והקו. הלימוד מחדש הוא על מכשיר המדריך בלבד (ai_gate), והמצלמה החיה מופנית לשולחן המדריך ולחפץ בלבד, לא לכיתה. בודקים את אותו חפץ שנפל, לא חפץ אחר. אם הוא עדיין נופל: גם זה מידע, כותבים ״לא״ ומה נצלם בפעם הבאה. מול הילדים אומרים ״המחשב״ ולא ״מודל״.

── סדר יום ──
• 2 ד׳ · בוחרים נפילה - קוראים את ספר הטעויות ומצביעים בכרטיסים על הנפילה שחזרה הכי הרבה.
• 4 ד׳ · 10 תמונות תיקון - שלושה זוגות מצלמים 10 תמונות של החפץ על הרקע שהפיל אותו; הידיים מאחורי הגב. הכיתה מנבאת: עדיין ייפול?
• 4 ד׳ · המדריך מלמד שוב ובודקים - סופרים עד 30, המדריך לוחץ ״למד״, ובודקים את אותו חפץ. כותבים ״כן״ או ״לא״ בעמודה ״התיקון עבד?״.

── הערכה ──
ראיות: שורה בספר הטעויות עם ״התיקון עבד?״ ממולא, ו-10 תמונות התיקון בגלריה.
הושלם כאשר: הכיתה בחרה נפילה אחת, צילמה 10 תמונות, והמחשב נבדק שוב על אותו חפץ.

── התאמות ──
קל יותר: המדריך בוחר את הנפילה ומצלם את 10 התמונות עם זוג אחד.
מאתגר יותר: שתי נפילות במקביל, ובודקים אם תיקון אחת שינה משהו בשנייה.$ws$, array[$ws$band:c-d$ws$, $ws$audience:school$ws$, $ws$level:L1$ws$, $ws$ai-mode:facilitator-trains$ws$, $ws$iteration$ws$, $ws$error_book$ws$]::text[], true)
