insert into public.ws_modules (slug, title, summary, module_type, pipeline_stage, duration_minutes, objectives, exercises, materials, facilitator_notes, tags, requires_app) values ($ws$assess-concept-check-gi$ws$, $ws$בדיקת מושגים: לפני ואחרי (ז-ט, רשות וארגונים)$ws$, $ws$סדר יום: הסבר (2 ד׳) · שמונה שאלות (7 ד׳) · אסיפה (1 ד׳)$ws$, $ws$practice$ws$, null, 10, array[$ws$למדוד התקדמות בשמונה מושגים: ביטחון, זיהוי מול סיווג, הטיה בדאטה, ציד כשלים, אתיקה ותחום, פיקסלים, גיוון, אימון ובדיקה.$ws$, $ws$לתת למדריך ספירות לפריט (״X מתוך Y״) לפני ואחרי, בלי ציון אישי.$ws$, $ws$לרשום שלושה פריטי גישה בנפרד מהידע.$ws$]::text[], $ws$[{"title": "שמונה שאלות", "instructions": "1. מחלקים את השאלון על טאבלט או מחשב של בית הספר או על נייר (לא בטלפון). בכל שאלה האפשרות האחרונה היא ״לא יודע/ת״.\n2. מענה עצמאי בשקט, 7 דקות. אותו שאלון בדיוק ב-pre וב-post.\n3. המדריך סופר לכל שאלה כמה ענו נכון (״X מתוך Y״); אחוזים רק כשיש 15 משיבים ומעלה, בלי פיצול לתת-קבוצות.\n4. ב-post חוזרים בקול על שתי השאלות שהכי הרבה טעו בהן ועל פריט ״ציד כשלים״.", "kind": "individual", "tool_hook": "none", "concept_check_id": "cc-gi", "questions": [{"q": "המודל אומר ״פח, בטוח ב-80%״. מה זה אומר?", "options": ["80% מהפח נראה בתמונה", "המודל די בטוח, אבל יכול לטעות", "יש 80 פחים", "לא יודע/ת"], "answer": 1, "id": "gi_confidence"}, {"q": "ההבדל בין ״יש פה פח״ ל״הפח נמצא פה״ הוא ההבדל בין:", "options": ["סיווג לזיהוי עם מסגרת", "תמונה לסרטון", "אימון לבדיקה", "לא יודע/ת"], "answer": 0, "id": "gi_detect"}, {"q": "קבוצה צילמה 200 תמונות של פחים, כולם מלאים, כולם בצהריים. מה הסיכון?", "options": ["אין סיכון, 200 זה הרבה", "המודל ילמד ״צהריים ופח מלא״ וייכשל בצל או על פח ריק", "המודל יהיה איטי", "לא יודע/ת"], "answer": 1, "core": "bias", "id": "gi_bias"}, {"q": "למה מחפשים בכוונה איפה המודל נופל?", "options": ["כדי לקבל ציון נמוך", "כדי לדעת מה לצלם בסבב הבא ומתי לא לסמוך עליו", "כי המדריך דורש", "לא יודע/ת"], "answer": 1, "id": "gi_failure_hunt"}, {"q": "הלקוח מבקש מודל שמזהה ״אנשים חשודים״ ליד בית הספר. מה התגובה הנכונה?", "options": ["לבנות, הלקוח צודק", "לסרב ולהציע חלופה שמזהה חפצים או מצבים, לא אנשים", "לבנות בלי לספר", "לא יודע/ת"], "answer": 1, "id": "gi_ethics"}, {"q": "מה מכונה ״רואה״ כשהיא מקבלת תמונה?", "options": ["תמונה כמו שאנחנו רואים", "טבלה של מספרים (פיקסלים)", "תיאור במילים", "רק את החפצים החשובים", "לא יודע/ת"], "answer": 1, "id": "gi_pixels"}, {"q": "מודל אומן רק על תמונות של כוס על שולחן לבן. מה הכי סביר שיקרה כשנצלם כוס על דשא?", "options": ["הוא יזהה בדיוק גבוה", "הוא עלול לטעות כי לא ראה רקע כזה", "הוא ילמד לבד", "זה לא משנה", "לא יודע/ת"], "answer": 1, "core": "variety", "id": "gi_variety"}, {"q": "למה מחלקים את התמונות לאימון ולבדיקה?", "options": ["כדי לחסוך מקום", "כדי לבדוק את המודל על תמונות שלא ראה", "כדי שהאימון יהיה מהיר יותר", "כדי להפחית תמונות", "לא יודע/ת"], "answer": 1, "core": "train_test", "id": "gi_test"}, {"q": "מעניין אותי ללמוד עוד על ראייה ממוחשבת (1 עד 5)", "options": ["1", "2", "3", "4", "5"], "answer": null, "note": "שאלת ביטחון עצמי או גישה, ללא תשובה נכונה."}, {"q": "אני מרגיש/ה שאני יכול/ה לבנות כזה מודל לבד (1 עד 5)", "options": ["1", "2", "3", "4", "5"], "answer": null, "note": "שאלת ביטחון עצמי או גישה, ללא תשובה נכונה."}, {"q": "בינה מלאכותית היא גם בשבילי (1 עד 5)", "options": ["1", "2", "3", "4", "5"], "answer": null, "note": "שאלת ביטחון עצמי או גישה, ללא תשובה נכונה."}]}, {"title": "טבלת סיכום", "instructions": "1. טבלה עם שמונה שורות ועמודה לכל אפשרות, כולל ״לא יודע/ת״.\n2. סופרים לכל שאלה כמה ענו נכון וכמה ״לא יודע/ת״; שומרים pre ו-post בנפרד, בלי שמות.\n3. ממוצע שלושת פריטי הגישה נשמר בנפרד מהידע.\n4. ב-post מציגים לכיתה את שלוש שאלות ה-core (גיוון, אימון ובדיקה, הטיה) כספירות.", "kind": "class", "tool_hook": "none"}]$ws$::jsonb, $ws$[{"label": "שאלון (8 שאלות + 3 פריטי גישה) על טאבלט או מחשב של בית הספר, או מודפס", "kind": "supply"}, {"label": "גיליון איסוף אנונימי", "kind": "supply"}]$ws$::jsonb, $ws$מקורות: בנק הפריטים של r7 (AI-CI של Zhang, Perry ו-Lee 2025; AILQ), [06 §4.4, §10]. אנונימיות היא תנאי: ספירות לפריט (״9 מתוך 12 אחרי, 4 מתוך 12 לפני״), אחוזים רק מ-15 משיבים, בלי פיצול לתת-קבוצות, pre ו-post לא מקושרים. ״לא יודע/ת״ נספר בנפרד ואינו טעות. אותו שאלון למבוגרים בסדנת הארגון ולכיתות ברשות. לא בטלפון: טאבלט או מחשב של בית הספר או נייר. בסדנת 6 המפגשים ה-pre רץ כמודול נפרד ב-10 הדקות הראשונות של מפגש 1 (מדלגים על ״בדיקת פתיחה״ המשובצת ב-core-s1) וה-post לפני התעודות במפגש 6.

── סדר יום ──
• 2 ד׳ · הסבר - בדיקה אנונימית, אין ציון אישי, אותה בדיקה בתחילת הסדנה ובסופה. מותר ״לא יודע/ת״.
• 7 ד׳ · שמונה שאלות - מענה עצמאי על טאבלט או מחשב של בית הספר או על נייר, ושלושה פריטי גישה בסולם 1 עד 5.
• 1 ד׳ · אסיפה - אוספים או סוגרים את הטופס, בלי שמות.

── הערכה ──
ראיות: ספירת נכונים לכל שאלה ב-pre וב-post, ספירת ״לא יודע/ת״ וממוצע פריטי הגישה.
הושלם כאשר: כל המשתתפים ענו בשני המועדים והמדריך שמר טבלת ספירות.

── התאמות ──
קל יותר: קריאת השאלות בקול למי שזקוק לכך; כרטיס מילים דו-לשוני.
מאתגר יותר: שאלה פתוחה ב-post: הסבירו למה 98% על תמונות דומות לאימון אינו מספר אמיתי.$ws$, array[$ws$assessment$ws$, $ws$pre_post$ws$, $ws$kirkpatrick_2$ws$, $ws$type:assessment$ws$, $ws$band:g-i$ws$, $ws$band:municipal$ws$, $ws$band:corporate$ws$, $ws$audience:school$ws$, $ws$audience:adult$ws$, $ws$audience:municipal$ws$, $ws$level:L3$ws$]::text[], false)
