insert into public.ws_modules (slug, title, summary, module_type, pipeline_stage, duration_minutes, objectives, exercises, materials, facilitator_notes, tags, requires_app) values ($ws$t-classroom-teaching-block$ws$, $ws$שלושה שיעורים בכיתה$ws$, $ws$סדר יום: שיעור 1 (90 ד׳) · שיעור 2 (90 ד׳) · שיעור 3 (90 ד׳)$ws$, $ws$practice$ws$, null, 270, array[$ws$להעביר בכיתה שלושה שיעורים של 90 דקות (או שישה של 45) מתוך הספרייה: cv-ab, cv-cd, cv-ef או cv-gi.$ws$, $ws$לתעד כל שיעור בתיק העבודות: pre/post של הכיתה, רשת גיוון, תמונות חפצים בלבד, רפלקציה של עמוד.$ws$, $ws$לקיים בכיתה את כללי המחשב והמצלמה: המצלמה על השולחן ועל חפצים, אף פעם לא על ילדים.$ws$, $ws$להוביל בעצמך את מקטע 5 הדקות שבסדנה מובילה המחנכת.$ws$]::text[], $ws$[{"title": "שיעור 1: פתיחה וכישלון מתוכנן", "instructions": "1. בוחרים תוכנית לפי הכיתה (א-ב, ג-ד, ה-ו או ז-ט) ומכינים את מודול הפתיחה שלה.\n2. מריצים pre מהבדיקה של הרצועה בשקט לפני הפעילות.\n3. מריצים את השיעור לפי הערות המדריך של המודול, עם המצלמה על השולחן בלבד.\n4. כותבים רפלקציה של עמוד: מה עבד, מה לא, מה אשנה.", "kind": "individual", "tool_hook": "none"}, {"title": "שיעור 2: דאטה ולימוד", "instructions": "1. מריצים את מודול הצילום או הלימוד של התוכנית.\n2. שומרים בתיק את רשת הגיוון או טבלת ה״X מתוך 10״ של הכיתה, בלי שמות.\n3. מתעדים נפילה אחת וכיצד הוסברה בתוך 30 שניות (א-ד) או השערה של הקבוצות (ז-ט).", "kind": "individual", "tool_hook": "none"}, {"title": "שיעור 3: בדיקה חוזרת וסיכום", "instructions": "1. מריצים את מודול הבדיקה או היריד של התוכנית, בלי דירוג.\n2. מריצים post באותם תנאים כמו ה-pre ומתעדים ספירות לפריט (״X מתוך Y״).\n3. מצרפים לתיק: שלוש רפלקציות, מכתב ההורים והמנהל שנשלח, ותמונות חפצים בלבד.", "kind": "individual", "tool_hook": "none"}]$ws$::jsonb, $ws$[{"label": "ספריית התוכניות: cv-ab, cv-cd, cv-ef, cv-gi (מודולים והערות מדריך)", "kind": "supply"}, {"label": "תבנית תיק עבודות (3 רפלקציות, pre/post, רשת גיוון)", "kind": "supply"}, {"label": "מכתב הורים ומנהל של בית הספר (מערב 3)", "kind": "supply"}, {"label": "טאבלטים או מחשבי בית הספר לפי מצב המכשיר של התוכנית", "kind": "supply"}]$ws$::jsonb, $ws$מקורות: [04 §9], [10 §9], r7 כלל 12 (השתלמות מתחת ל-14 שעות אינה משפיעה על תלמידים; 30-100 שעות כן). המפגש אינו מפגש סינכרוני: הוא 270 דקות של הוראה בכיתה של המורה בין ערב 8 לערב הסיום, והוא קיים בתוכנה כדי ש-30 השעות יהיו מלאות ושהתיק יהיה מתועד. המדריך אינו נוכח; המורה מריץ/ה לבד ומדווח/ת דרך התיק. בכל שיעור: המצלמה על השולחן או על חפצים, אף פעם לא על ילדים; הצבעות בכרטיסים נספרות בקול; בכיתות א-ד אומרים ״המחשב״ או ״רובי״ ולא ״מודל״; תוצאות כספירה ״X מתוך 10 תמונות חדשות״. מקטע 5 הדקות שבסדנה מובילה המחנכת: כאן המורה מוביל/ה הכול.

── סדר יום ──
• 90 ד׳ · שיעור 1 - פתיחה וכישלון מתוכנן מתוך התוכנית שנבחרה, אחרי pre בשקט. רפלקציה של עמוד.
• 90 ד׳ · שיעור 2 - צילום או לימוד; רשת גיוון או טבלת ״X מתוך 10״ נשמרות בתיק בלי שמות.
• 90 ד׳ · שיעור 3 - בדיקה חוזרת או יריד בלי דירוג, post באותם תנאים, סגירת התיק.

── הערכה ──
ראיות: תיק עבודות עם שלוש רפלקציות, ספירות pre/post לפריט, רשת גיוון ותמונות חפצים בלבד.
הושלם כאשר: שלושת השיעורים הועברו ותועדו, וה-pre וה-post של הכיתה נספרו.

── התאמות ──
קל יותר: שישה שיעורים של 45 דקות במקום שלושה של 90, או שיעור אחד בהנחיה משותפת עם המדריך.
מאתגר יותר: שיעור אחד מצולם (חפצים ולוח בלבד, בלי ילדים) ומובא לתצפית עמיתים בערב הסיום.$ws$, array[$ws$band:teachers$ws$, $ws$audience:teachers$ws$, $ws$level:all$ws$, $ws$practicum$ws$, $ws$portfolio$ws$, $ws$classroom_teaching$ws$]::text[], false)
