 where slug = $ws$cv-ef-vision-lab$ws$ and (requires_product, ai_gate_note) is distinct from (array[$ws$click_a_point$ws$, $ws$parallel_training_queue$ws$, $ws$teacher_run_training$ws$, $ws$staff_training_submit$ws$, $ws$misses_gallery$ws$]::text[], $ws$עד שהפריטים קיימים (strategy §6 פריטים 6, 9, 17): תיוג ידני עם ידיות 44 פיקסלים ובדיקת מדריך על תיבה אחת מכל עשר, ותוצאות תמיד במצב B (אימון לילי, קריאת תוצאות בפתיחת המפגש הבא). אין הבטחה לתוצאות באותו מפגש. הגשה לאימון בלי כפתור צוות בקונסולה: המדריך מגיש מהמחשב שלו, תמיד במצב B. גלריית פספוסים בלי רכיב באפליקציה: המדריך מצלם מסך או מדפיס 3 תמונות פספוס לכל קבוצה, והגלריה היא על קיר הכיתה. התוכנית נשארת live עם ה-fallback הזה.$ws$);

