            where j.tslug = r.tslug and j.session_no = x.session_no and jm.id = x.module_id);
      v_last := r.tslug;
    end if;
    -- take the first not-yet-placed row of this (session, module); insert if none
    select id into v_id from public.ws_template_modules
     where template_id = v_t and session_no = r.session_no and module_id = v_m and position > 250
     order by position limit 1;
    if v_id is null then
      insert into public.ws_template_modules (template_id, module_id, session_no, position, session_title, session_kind, notes)
      values (v_t, v_m, r.session_no, 10 * r.k, r.session_title, r.session_kind, r.notes);
    else
      update public.ws_template_modules
         set position = 10 * r.k, session_title = r.session_title, session_kind = r.session_kind, notes = r.notes
       where id = v_id;
    end if;
  end loop;
end $do$;
-- 4c. baseline templates (0005 rows keep their notes): check rows at the start/end of the named sessions, addenda appended
do $do$
declare v_t uuid; v_gi uuid; v_min int; v_max int; r record;
begin
  select id into v_gi from public.ws_modules where slug = $ws$assess-concept-check-gi$ws$;
  if v_gi is null then raise exception 'module assess-concept-check-gi missing'; end if;
  for r in select * from (values
  ($ws$corewise-6-sessions$ws$, 1, $ws$start$ws$, $ws$איך מכונה רואה$ws$, $ws$regular$ws$),
  ($ws$corewise-6-sessions$ws$, 6, $ws$end$ws$, $ws$Demo Day$ws$, $ws$demo_day$ws$),
  ($ws$hackathon-day$ws$, 1, $ws$start$ws$, $ws$יום האקתון$ws$, $ws$hackathon$ws$),
  ($ws$hackathon-day$ws$, 1, $ws$end$ws$, $ws$יום האקתון$ws$, $ws$hackathon$ws$),
  ($ws$corporate-half-day$ws$, 1, $ws$start$ws$, $ws$חצי יום$ws$, $ws$other$ws$),
  ($ws$corporate-half-day$ws$, 1, $ws$end$ws$, $ws$חצי יום$ws$, $ws$other$ws$)
    ) as v(tslug, session_no, place, session_title, session_kind) order by tslug, session_no, place
  loop
    select id into v_t from public.ws_curriculum_templates where slug = r.tslug;
    if v_t is null then raise exception 'template % missing', r.tslug; end if;
    -- dense 1..n (as seeded by 0005) -> 10..10n, once
    if (select max(position) from public.ws_template_modules where template_id = v_t)
       = (select count(*) from public.ws_template_modules where template_id = v_t) then
      update public.ws_template_modules set position = position * 10 where template_id = v_t;
    end if;
    select min(position), max(position) into v_min, v_max from public.ws_template_modules
     where template_id = v_t and session_no = r.session_no and module_id <> v_gi;
    if v_min is null then raise exception 'template % has no rows in session %', r.tslug, r.session_no; end if;
    if v_min < 6 then raise exception 'template % session % positions were edited by hand (min %); renumber before applying', r.tslug, r.session_no, v_min; end if;
    if r.place = 'start' and not exists (select 1 from public.ws_template_modules
         where template_id = v_t and session_no = r.session_no and module_id = v_gi and position < v_min) then
      insert into public.ws_template_modules (template_id, module_id, session_no, position, session_title, session_kind, notes)
      values (v_t, v_gi, r.session_no, v_min - 5, r.session_title, r.session_kind, $ws$בדיקת pre (assess-concept-check-gi, 10 דקות) בשקט לפני הפתיחה. ספירות לפריט, ״לא יודע/ת״ מותר.$ws$);
    elsif r.place = 'end' and not exists (select 1 from public.ws_template_modules
         where template_id = v_t and session_no = r.session_no and module_id = v_gi and position > v_max) then
      insert into public.ws_template_modules (template_id, module_id, session_no, position, session_title, session_kind, notes)
      values (v_t, v_gi, r.session_no, v_max + 5, r.session_title, r.session_kind, $ws$בדיקת post (assess-concept-check-gi, 10 דקות) לפני התעודות, באותם תנאים כמו ה-pre.$ws$);
    end if;
  end loop;
  -- notes addenda on the first original row of each session (the row with the lowest position that is not the check)
  for r in select * from (values
  ($ws$corewise-6-sessions$ws$, 1, $ws$בדיקת המושגים (assess-concept-check-gi) רצה כמודול נפרד ב-10 הדקות הראשונות; מדלגים על משבצת ״בדיקת פתיחה״ המשובצת במודול. בהדגמת הזיהוי החי המצלמה מופנית לשולחן ולחפצים, לא לתלמידים. מציגים כבר היום את קריטריוני ההצטיינות (סט בדיקה מופרד, ספר טעויות מלא, דאטה מגוון, כנות על כשלים). המחנכת מובילה 5 דקות: החוזה הכיתתי.$ws$),
  ($ws$corewise-6-sessions$ws$, 2, $ws$המחנכת מובילה 5 דקות: סיכום שאלות הלקוח.$ws$),
  ($ws$corewise-6-sessions$ws$, 3, $ws$כשמודל נופל, הקבוצות משערות סיבה לפני שהמדריך מסביר. המחנכת מובילה 5 דקות: משחק אימון מול בדיקה.$ws$),
  ($ws$corewise-6-sessions$ws$, 4, $ws$לפני ההעלאה: כל קבוצה חותמת 10 תמונות לכל מחלקה ב״מעטפת הבדיקה״ (לא נשלחות לאימון). סבב כיול תיבות של 10 דקות: כל הזוגות מסמנים תיבות על אותן 5 תמונות משותפות, משווים על המקרן וכותבים 3 כללי תיבה; 10 הדקות באות על חשבון ספרינט התיוג. טאבלטים או מחשבי בית הספר, לא טלפונים. המחנכת מובילה 5 דקות: ספירת המעטפות (10 תמונות לכל מחלקה).$ws$),
  ($ws$corewise-6-sessions$ws$, 5, $ws$מודל A מאומן בידי המדריך בין מפגש 4 ל-5 ונטען בפתיחה. ציד כשלים: הקבוצות משערות ומצלמות תיקון לפני שהמדריך מסביר. אימון חוזר (מודל B) מוגש באפשרות המהירה עד דקה 70; אחריו בלוק בלי מסך (עלות הטעות, שלד המצגת). תוצאות על מעטפת הבדיקה כספירה, ״X מתוך 10 תמונות חדשות״: מצא / פספס / התריע סתם, לפני כל ציון. אם B לא חזר עד דקה 95: משווים A מול B בפתיחת מפגש 6. המחנכת מובילה 5 דקות: סיכום ציד הכשלים: כל קבוצה אומרת השערה אחת.$ws$),
  ($ws$corewise-6-sessions$ws$, 6, $ws$בדיקת ה-post (assess-concept-check-gi) רצה כמודול נפרד לפני התעודות; מדלגים על ״בדיקת סיום״ המשובצת במודול. פתיחה: אם B לא הושווה, משווים A מול B על מעטפת הבדיקה בספירה. אין דירוג לפי דיוק; הצטיינות לפי קריטריונים שהוצגו במפגש 1, בלי מכסה. מבחני ההפלה בהדגמה נבחרים על ידי הקבוצה; המצלמה על חפצים. המחנכת מובילה 5 דקות: הצגת הקריטריונים בפתיחת Demo Day.$ws$),
  ($ws$hackathon-day$ws$, 1, $ws$pre (assess-concept-check-gi) 10 דקות בפתיחה לפני hd-kickoff; post 10 דקות אחרי hd-demo-ceremony. בספרינט הדאטה: חותמים 10 תמונות לכל מחלקה במעטפה לפני ההעלאה; תוצאות כספירה ״X מתוך 10 תמונות חדשות״ לפני כל ציון. אין דירוג לפי דיוק. המצלמה על חפצים, לא על תלמידים. המחנכת מובילה 5 דקות: סיכום ציד הכשלים לפני הפיצ׳ים.$ws$),
  ($ws$corporate-half-day$ws$, 1, $ws$pre ו-post (assess-concept-check-gi) 10 דקות בפתיחה ובסיום. תוצאות כספירה ״X מתוך 10 תמונות חדשות״ לפני כל ציון; המצלמה על חפצים, לא על עובדים. מנהל/ת הצוות מוביל/ה 5 דקות: סיכום ההחלטה (ממשיכים, מתקנים, עוצרים).$ws$)
    ) as v(tslug, session_no, addendum)
  loop
    select id into v_t from public.ws_curriculum_templates where slug = r.tslug;
    update public.ws_template_modules x
       set notes = case when coalesce(x.notes, '') = '' then r.addendum else x.notes || E'\n' || r.addendum end
     where x.id = (select id from public.ws_template_modules
                    where template_id = v_t and session_no = r.session_no and module_id <> v_gi order by position limit 1)
       and strpos(coalesce(x.notes, ''), r.addendum) = 0;
  end loop;
end $do$;

-- ═══ 5. existing workshops: add ws_session_modules rows their template gained (matched by session_no) ═══
-- PILOT-1 (8a9dfe81-a317-4dc2-89d8-0a7e5c6433a3, corewise-6-sessions) gets the pre check at position 1 of session 1 and the post check after core-s6 in session 6.
do $do$
declare w record; s record; tm record; v_need int; v_have int; v_pos int;
begin
  for w in select ws.id, ws.template_id from public.ws_workshops ws join public.ws_curriculum_templates t on t.id = ws.template_id
            where t.slug in ($ws$corewise-6-sessions$ws$, $ws$corporate-half-day$ws$, $ws$cv-ab-i-am-the-model$ws$, $ws$cv-cd-teach-the-class-tablet$ws$, $ws$cv-ef-hackathon-halfday$ws$, $ws$cv-ef-vision-lab$ws$, $ws$cv-gi-research-club$ws$, $ws$cv-jl-client-track-8x90$ws$, $ws$cv-jl-hackathon-2day$ws$, $ws$cv-municipal-10-classes$ws$, $ws$cv-teachers-pd-30h$ws$, $ws$hackathon-day$ws$) and ws.status not in ('completed', 'archived', 'cancelled')
  loop
    for s in select id, session_no from public.ws_sessions where workshop_id = w.id order by session_no loop
      for tm in select x.*, m.version, m.title, m.module_type, m.duration_minutes as m_duration, m.pipeline_stage, m.summary,
                       m.objectives, m.exercises, m.materials, m.facilitator_notes,
                       (x.position = min(x.position) over ()) as is_first
                  from public.ws_template_modules x join public.ws_modules m on m.id = x.module_id
                 where x.template_id = w.template_id and x.session_no = s.session_no order by x.position
      loop
        select count(*) into v_need from public.ws_template_modules
         where template_id = w.template_id and session_no = s.session_no and module_id = tm.module_id and position <= tm.position;
        select count(*) into v_have from public.ws_session_modules where session_id = s.id and module_id = tm.module_id;
        if v_have < v_need then
          if tm.is_first then
            update public.ws_session_modules set position = position + 1 where session_id = s.id;
            v_pos := 1;
          else
            select coalesce(max(position), 0) + 1 into v_pos from public.ws_session_modules where session_id = s.id;
          end if;
          insert into public.ws_session_modules (session_id, workshop_id, module_id, module_version, position,
                                                 title, module_type, duration_minutes, pipeline_stage, content)
          values (s.id, w.id, tm.module_id, tm.version, v_pos, tm.title, tm.module_type,
                  coalesce(tm.duration_override, tm.m_duration), tm.pipeline_stage,
                  jsonb_build_object('summary', tm.summary, 'objectives', to_jsonb(tm.objectives),
                    'exercises', tm.exercises, 'materials', tm.materials,
                    'facilitator_notes', tm.facilitator_notes, 'template_notes', tm.notes));
        end if;
      end loop;
    end loop;
  end loop;
end $do$;

-- ═══ 6. re-snapshot content of existing session modules from their module rows (same shape as ws_instantiate_curriculum) ═══
-- template_notes: the matching template row's notes when the workshop still has its template; otherwise the old value is kept.
-- status, notes, duration_minutes and position of the session module are not touched.
with src as (
  select sm.id as sm_id, m.title, m.module_type, m.pipeline_stage, m.version,
         jsonb_build_object('summary', m.summary, 'objectives', to_jsonb(m.objectives),
           'exercises', m.exercises, 'materials', m.materials,
           'facilitator_notes', m.facilitator_notes,
           'template_notes', coalesce(
             (select tm.notes from public.ws_template_modules tm
               where tm.template_id = ws.template_id and tm.session_no = s.session_no and tm.module_id = sm.module_id
               order by tm.position limit 1),
             sm.content->>'template_notes')) as content
    from public.ws_session_modules sm
    join public.ws_modules m on m.id = sm.module_id
    join public.ws_sessions s on s.id = sm.session_id
    join public.ws_workshops ws on ws.id = sm.workshop_id
   where m.slug in ($ws$ab-human-classifier$ws$, $ws$ab-facilitator-live-demo$ws$, $ws$ab-expo-robots$ws$, $ws$ab-mistake-and-bias$ws$, $ws$ab-variety-and-album$ws$, $ws$assess-concept-check-ab$ws$, $ws$x-failed-model-opener$ws$, $ws$cd-resolution-reveal$ws$, $ws$cd-capture-variety-walk$ws$, $ws$cd-pocket-three-objects$ws$, $ws$cd-break-the-model-game$ws$, $ws$cd-confidence-line$ws$, $ws$cd-class-fair$ws$, $ws$assess-concept-check-cd$ws$, $ws$ef-click-a-point-tagging$ws$, $ws$bridge-hidden-envelope$ws$, $ws$ef-labeling-guide-race$ws$, $ws$ef-read-results-and-gallery$ws$, $ws$ef-fair-booths$ws$, $ws$ehd-train-bridge-retest$ws$, $ws$ehd-fair-and-certificates$ws$, $ws$assess-concept-check-ef$ws$, $ws$gi-hard-negatives-and-flip$ws$, $ws$gi-confusion-matrix-and-error-cost$ws$, $ws$jl-datasheet-and-split$ws$, $ws$jl-confusion-matrix-by-hand$ws$, $ws$jl-threshold-pr-curve$ws$, $ws$jl-sliced-error-analysis$ws$, $ws$jl-client-readout-demo$ws$, $ws$jhd-iterate-sprint$ws$, $ws$assess-concept-check-jl$ws$, $ws$t-assessment-evidence-pack$ws$, $ws$mun-city-demo-day$ws$, $ws$cd-fix-one-fall$ws$, $ws$assess-concept-check-gi$ws$, $ws$t-classroom-teaching-block$ws$)
)
update public.ws_session_modules sm
   set content = src.content, title = src.title, module_type = src.module_type, pipeline_stage = src.pipeline_stage,
       module_version = src.version, updated_at = now()
  from src
 where sm.id = src.sm_id
   and (sm.content, sm.title, sm.module_type, sm.pipeline_stage, sm.module_version)
       is distinct from (src.content, src.title, src.module_type, src.pipeline_stage, src.version);
commit;
